static void FakeOnButton(uint8_t *self, const FakeEvent *e)
{
	float *move = *(float **)(self + 0x10);
	if (g_handlerStyle == 1) {
		move[0] += e->x;
		move[1] += e->y;
	} else {
		if (e->axis != 2)
			move[0] = e->x;
		if (e->axis != 1)
			move[1] = e->y;
	}
}
