		Keys(0.0f, 1.0f);
		FxWaterAt(640.0f, 3500);
		FxSetWater(true, 20.0f, -60.0f);
		before[k] = FxWaterAt(640.0f, 2500);
		*(uint32_t *)(g_fakeUi56 + 0x1E0) = 1u;
