static int Q57Lines(const char *a, const char *b)   /* lines holding both texts */
{
	static char line[4096];
	FILE *f = OpenLog();
	if (!f)
		return -1;
	int n = 0;
	while (fgets(line, sizeof(line), f))
		if (strstr(line, a) && (!b || strstr(line, b)))
			n++;
	fclose(f);
	return n;
}

