/* --- Climbing low things (test 40's finding 8; mode 10) ------------------------------------
 * The player's capsule (radius 18) stopped by what it meets, as f8's capsule model has it: a
 * contact steeper than the limit the controller holds now (acos of *Slope()) is a wall, so the
 * axis is held 18 short of the face; within the limit, the push into the contact slides the
 * capsule up it (the push times sin a cos a, the contact's angle held), and once the feet are at
 * the top less 0.5 it is let through, on top, till the axis is past the far side. The contact's
 * angle: acos((18 - T/2)/(18 + T/2)) for a round log T across, acos(1 - T/18) for a sharp step
 * of T (90 from 18 up: the capsule's upright side). Only the planes given a kind here, and only
 * in mode 10 (R4); the feet follow the rays' ground there (a slope, the kink) with the lift. */
enum { CAP_NONE, CAP_LOG, CAP_STEP };
#define CAPSULE_R 18.0f
static bool g_capsuleOn;
static int g_capKind[3];
static float g_capDepth[3];     /* how far the thing reaches past its face, for when the axis is past it */
static float g_feetLift;        /* the feet over the ground: onto what the capsule climbed */
static int g_capHeld;           /* frames the capsule was held at a face it couldn't climb */
/* Test 42's railing (new 1): held at a face, the capsule slides along it, the push into it taken
 * off; the game kept about 0.4 of the speed along it, a trace line (0.25 s) after the contact
 * (850 -> 358, 683 -> 338 with the input at full): the motion along the face is kept at this
 * share while in contact (1: all of it, the frictionless slide every other check rides). */
static float g_capSlip = 1.0f;
static float GroundZAt(float x, float y)
{
	float u = (x - g_slopeO[0]) * g_slopeD[0] + (y - g_slopeO[1]) * g_slopeD[1];
	if (g_kinkOn && u > g_kinkAt)
		u = g_kinkAt;
	return g_groundZ + g_slopeK * u;
}
static float ContactAngle(int kind, float T)
{
	if (kind == CAP_LOG)
		return acosf((CAPSULE_R - 0.5f * T) / (CAPSULE_R + 0.5f * T)) * DEG;
	return T >= CAPSULE_R ? 90.0f : acosf(1.0f - T / CAPSULE_R) * DEG;
}
static void CapsuleStop(const float before[2])
{
	float *p = PlayerPos(), lift = 0.0f;
	float raised = p[2] - GroundZAt(before[0], before[1]);   /* the feet over the ground now: the plugin's SetPosition (stage 2's step up) may have put them up since the last frame (over the ground where they stood before this frame's move: on a slope down, the ground under the moved feet is lower, and a capsule held at a face crept up it) */
	for (int i = 0; i < 3; i++) {
		const FakePlane *w = &g_planes[i];
		if (!w->on || !g_capKind[i] || w->follow != 0.0f)
			continue;
		float T = w->top > 0.0f ? w->top : 10000.0f;
		float s = (p[0] - w->point[0]) * w->normal[0] + (p[1] - w->point[1]) * w->normal[1];
		if (s > CAPSULE_R + 0.05f || s < -g_capDepth[i])
			continue;   /* not touching it, or the axis past its far side */
		float have = g_planeTopDepth[i] > 0.0f && raised > g_feetLift ? raised : g_feetLift;   /* a step up counts only at a thing with a top (stage 2's checks; R4) */
		if (have >= T - 0.5f) {
			lift = fmaxf(lift, T);   /* on top of it: let through */
			continue;
		}
		float sb = (before[0] - w->point[0]) * w->normal[0] + (before[1] - w->point[1]) * w->normal[1];
		float a = ContactAngle(g_capKind[i], T) / DEG, push = sb - s > 0.0f ? sb - s : 0.0f, up = have;
		if (s < CAPSULE_R) {   /* held at the contact */
			p[0] += w->normal[0] * (CAPSULE_R - s);
			p[1] += w->normal[1] * (CAPSULE_R - s);
			if (g_capSlip < 1.0f) {   /* the game's loss along it (test 42) */
				float tx = -w->normal[1], ty = w->normal[0], m = (p[0] - before[0]) * tx + (p[1] - before[1]) * ty;
				p[0] -= (1.0f - g_capSlip) * m * tx;
				p[1] -= (1.0f - g_capSlip) * m * ty;
			}
		}
		if (a <= acosf(*Slope()) + 1e-4f)
			up += push * sinf(a) * cosf(a);   /* within the limit: slid up it */
		else
			g_capHeld++;
		lift = fmaxf(lift, up);
	}
	g_feetLift = lift;
	p[2] = GroundZAt(p[0], p[1]) + g_feetLift;
}
static void ClimbFrame(float dt)
{
	float before[2] = { PlayerPos()[0], PlayerPos()[1] };
	FakeGameFrame(dt);
	if (g_capsuleOn)
		CapsuleStop(before);
}
/* One frame of the game and the plugin, no wait (a cut within a frame). */
static void OneFrame(void)
{
	if (g_fixed66)
		FixedAdvance66(FIXED_WORK66);   /* 2026-11-24: in a fixed stretch the plugin's clock on by a frame's work (no sleep here) */
	if (g_onFrame)
		g_onFrame(0.005f);
	SyncFakeWorld();
	((void (*)(Task *))g_task->vtbl[1])(g_task);
	if (g_afterTask)
		g_afterTask(0.005f);
	if (*Slope() < g_slopeMin)
		g_slopeMin = *Slope();
}
/* Plane i a thing `ahead` units ahead of the player's axis, facing them, `top` tall above the
 * ground (0: no top), of a capsule kind, reaching `depth` past its face. */
static FakePlane *Obstacle(int i, float ahead, float top, int kind, float depth, uint32_t layer, uint8_t *what)
{
	FakePlane *w = &g_planes[i];
	float h = PlayerHeading(), fx = sinf(h), fy = cosf(h);
	memset(w, 0, sizeof(*w));
	w->point[0] = PlayerPos()[0] + fx * ahead;
	w->point[1] = PlayerPos()[1] + fy * ahead;
	w->normal[0] = -fx;
	w->normal[1] = -fy;
	w->layer = layer;
	w->top = top;
	w->what = what;
	w->on = true;
	g_capKind[i] = kind;
	g_capDepth[i] = depth;
	g_planeTopDepth[i] = 0.0f;   /* no top the rays down see, unless a stage-2 check gives it one */
	g_capHeld = 0;
	return w;
}
static float FaceGap(const FakePlane *w)   /* the axis to the face, + in front of it */
{
	return (PlayerPos()[0] - w->point[0]) * w->normal[0] + (PlayerPos()[1] - w->point[1]) * w->normal[1];
}
static void ClearObstacles(void)
{
	for (int i = 0; i < 3; i++) {
		g_planes[i].on = false;
		g_capKind[i] = CAP_NONE;
		g_planeTopDepth[i] = 0.0f;
	}
	g_feetLift = 0.0f;
	PlayerPos()[2] = GroundZAt(PlayerPos()[0], PlayerPos()[1]);
}
/* W held up to ms: the seconds until the axis is past the thing's far side (-1: it isn't). */
static float RideAt(const FakePlane *w, float depth, int ms)
{
	Keys(0.0f, 1.0f);
	for (int t = 0; t < ms; t += 50) {
		RunFrames(50);
		if (FaceGap(w) < -depth)
			return (float)(t + 50) / 1000.0f;
	}
	return -1.0f;
}
/* W held up to ms until the climb's boost is in the slot: the seconds it took (-1: never). */
static float UntilBoost(float boostCos, int ms)
{
	Keys(0.0f, 1.0f);
	for (int t = 0; t < ms; t += 25) {
		RunFrames(25);
		if (Near(*Slope(), boostCos))
			return (float)(t + 25) / 1000.0f;
	}
	return -1.0f;
}
static void RollOff(void)   /* W let go of, the obstacles gone, rolled off to a stop */
{
	Keys(0.0f, 0.0f);
	ClearObstacles();
	RunFrames(2500);
}
static void GetOffAndOn(float degrees)
{
	Keys(0.0f, 0.0f);
	SetLive(0.0f);
	SetCamera(0.0f);
	SetTilt(0.0f);
	RunFrames(400);
	SetLive(degrees);
	SetCamera(300.0f);
	SetTilt(30.0f);
	RunFrames(1000);
}
static int FaceLines(void) { return LogLines("past the front wheel at axle height") + LogLines("rays: nothing ahead now"); }

/* Stage 2 (test 41, ClimbStep; plan check 9): a sharp step 26 high and 60 deep, a stump. Its
 * contact is on the capsule's upright side (acos(1 - 26/18): 90), so no limit climbs it; its top
 * is a flat surface the plugin's rays down find (g_planeTopDepth, these checks only), and the
 * capsule model takes the feet put up by SetPosition as on top of it. Each part on a ride of its
 * own, so the climb's hand of 10 lines is full at its start. */
static void ClimbStepTests(void)
{
	float *head = (float *)(g_player + 0xC8), cos85 = cosf(85.0f / DEG);
	FakePlane *w;
	float passed;

	printf("climb, stage 2 (ClimbStep=1): a sharp step 26 high and 60 deep 400 ahead (its contact on the capsule's upright side), its top where rays down find it, SetPosition honoured, W held: stepped up 27.5 and 4 on, at most twice, over it:\n");
	GetOffAndOn(45.0f);
	g_camYaw = *head;
	CHECK(LogLines("a sharp step the limit can't take stepped up onto (ClimbStep=1)") >= 1 && LogLines("low things up to 31.9 above the feet climbed with the limit at 85 deg while forward is held, sharp steps up to it stepped up onto") >= 1,
	      "the settings line and the ride's capsule line say ClimbStep=1");
	{
		int step0 = LogLines("climb: stepped up 27.5 (the top 26.0 at "), over0 = LogLines("climb: over it after"), after0 = LogLines(", after 1 step up): the climb limit back to 47");
		int noStep0 = LogLines("climb: no step:"), didnt0 = LogLines("climb: the step up didn't take"), sets0 = g_setPositions;
		g_slopeMin = 1.0f;
		w = Obstacle(0, 400.0f, 26.0f, CAP_STEP, 60.0f, 1, NULL);
		g_planeTopDepth[0] = 60.0f;
		g_rec = true;
		g_recN = 0;
		passed = RideAt(w, 60.0f, 4000);
		g_rec = false;
		float steepest = g_slopeMin;
		RunFrames(500);
		int steps = g_recN;
		bool sized = steps > 0;
		for (int i = 0; i < steps; i++)
			sized = sized && fabsf(g_recDz[i] - 27.5f) <= 0.5f && fabsf(g_recStep[i] - 4.0f) <= 0.05f;
		CHECK(passed > 0.0f, "over it within 4 s (%.2f s; the capsule held at it %d frames)", passed, g_capHeld);
		CHECK(steps >= 1 && steps <= 2 && sized && g_setPositions - sets0 == steps, "stepped up %d time(s) (SetPosition called %d), each by the top + 1.5 (%.2f) and 4 on (%.2f)",
		      steps, g_setPositions - sets0, steps ? g_recDz[0] : 0.0f, steps ? g_recStep[0] : 0.0f);
		CHECK(LogLines("climb: stepped up 27.5 (the top 26.0 at ") - step0 == steps && LogLines("climb: over it after") - over0 == 1 && LogLines(", after 1 step up): the climb limit back to 47") - after0 == (steps == 1) &&
		      LogLines("climb: no step:") == noStep0 && LogLines("climb: the step up didn't take") == didnt0,
		      "a \"stepped up 27.5 (the top 26.0 at ...\" line a step (%d), one \"over it ... after 1 step up\" (%d), no \"no step\" or \"didn't take\" line",
		      LogLines("climb: stepped up 27.5 (the top 26.0 at ") - step0, LogLines("climb: over it after") - over0);
		CHECK(Near(steepest, cos85) && Near(*Slope(), COS47), "the boost at it (the steepest limit %.2f deg), 47 again after (%.2f deg)", acosf(steepest) * DEG, acosf(*Slope()) * DEG);
		RollOff();
	}

	printf("climb, stage 2: the same step with SetPosition not honoured, W held: two steps asked, both said not to have taken, given up after 1.5 s stalled, 47; forward pressed again: the boost again, no more steps at this obstacle:\n");
	GetOffAndOn(45.0f);
	g_camYaw = *head;
	{
		int sets0 = g_setPositions, didnt0 = LogLines("climb: the step up didn't take"), given0 = LogLines("climb: given up after"), made0 = LogLines(", 2 steps up made): not again");
		int low0 = LogLines("climb: a low face at the capsule");
		g_honour = 0;
		w = Obstacle(0, 400.0f, 26.0f, CAP_STEP, 60.0f, 1, NULL);
		g_planeTopDepth[0] = 60.0f;
		passed = RideAt(w, 60.0f, 3500);
		CHECK(passed < 0.0f && FaceGap(w) > 17.0f && g_setPositions - sets0 == 2 && LogLines("climb: the step up didn't take") - didnt0 == 2,
		      "held at it (the axis %.1f from its face): 2 steps asked (%d), both said not to have taken (%d)", FaceGap(w), g_setPositions - sets0, LogLines("climb: the step up didn't take") - didnt0);
		CHECK(LogLines("climb: given up after") - given0 == 1 && LogLines(", 2 steps up made): not again") - made0 == 1 && Near(*Slope(), COS47),
		      "given up (%d line, \"2 steps up made\"), back to 47 (%.2f deg)", LogLines("climb: given up after") - given0, acosf(*Slope()) * DEG);
		RunFrames(1000);
		CHECK(LogLines("climb: a low face at the capsule") - low0 == 1 && Near(*Slope(), COS47), "W still held 1 s: not again (%d boost line), 47 (%.2f deg)", LogLines("climb: a low face at the capsule") - low0, acosf(*Slope()) * DEG);
		Keys(0.0f, 0.0f);
		RunFrames(300);
		int sets1 = g_setPositions;
		float took = UntilBoost(cos85, 1000);
		RunFrames(1500);
		CHECK(took > 0.0f && g_setPositions == sets1, "forward pressed again: the boost on again (%.2f s), but no step (SetPosition called %d more): two an obstacle", took, g_setPositions - sets1);
		Keys(0.0f, 0.0f);
		g_honour = 4;
		RollOff();
	}

	printf("climb, stage 2: the same step with something 90 over its top (no room for the capsule's 128), W held: no step, \"no room above it\", given up:\n");
	GetOffAndOn(45.0f);
	g_camYaw = *head;
	{
		int sets0 = g_setPositions, room0 = LogLines("climb: no step: no room above it (FakeShelf, layer 1, 90 over the top 26.0"), given0 = LogLines("climb: given up after");
		w = Obstacle(0, 400.0f, 26.0f, CAP_STEP, 60.0f, 1, NULL);
		g_planeTopDepth[0] = 60.0f;
		g_shelfOn = true;   /* a disc 116 over the ground, 10 to 60 ahead of the player wherever they are: over the step's top, not over the axis or a wheel */
		g_shelfHeight = 116.0f;
		g_shelfAhead = 35.0f;
		g_shelfRadius = 25.0f;
		passed = RideAt(w, 60.0f, 3500);
		CHECK(passed < 0.0f && FaceGap(w) > 17.0f && g_setPositions == sets0, "held at it (the axis %.1f from its face), no SetPosition (%d)", FaceGap(w), g_setPositions - sets0);
		CHECK(LogLines("climb: no step: no room above it (FakeShelf, layer 1, 90 over the top 26.0") - room0 == 1 && LogLines("climb: given up after") - given0 == 1,
		      "one \"no step: no room above it (FakeShelf, layer 1, 90 over the top 26.0 ...\" line (%d), given up (%d)",
		      LogLines("climb: no step: no room above it (FakeShelf, layer 1, 90 over the top 26.0") - room0, LogLines("climb: given up after") - given0);
		Keys(0.0f, 0.0f);
		g_shelfOn = false;
		g_shelfHeight = g_shelfAhead = 0.0f;
		g_shelfRadius = 60.0f;
		RollOff();
	}

	printf("climb, stage 2: ClimbStep=0 written (read again on getting on), the same step, SetPosition honoured, W held: no step, held, given up (the boost alone, as stage 1 shipped):\n");
	RewriteIni("Climb=1\n", "Climb=1\nClimbStep=0\n");
	GetOffAndOn(45.0f);
	g_camYaw = *head;
	{
		int sets0 = g_setPositions, given0 = LogLines("climb: given up after"), step0 = LogLines("climb: stepped up"), noStep0 = LogLines("climb: no step:");
		CHECK(LogLines("; sharp steps not stepped up onto (ClimbStep=0) (read again on getting on)") >= 1, "the settings line says ClimbStep=0");
		w = Obstacle(0, 400.0f, 26.0f, CAP_STEP, 60.0f, 1, NULL);
		g_planeTopDepth[0] = 60.0f;
		passed = RideAt(w, 60.0f, 3500);
		CHECK(passed < 0.0f && FaceGap(w) > 17.0f && g_setPositions == sets0 && LogLines("climb: stepped up") == step0 && LogLines("climb: no step:") == noStep0 && LogLines("climb: given up after") - given0 == 1,
		      "held at it (the axis %.1f from its face), no SetPosition (%d), no step line, given up (%d)", FaceGap(w), g_setPositions - sets0, LogLines("climb: given up after") - given0);
		Keys(0.0f, 0.0f);
		RollOff();
	}
	RewriteIni("ClimbStep=0", "ClimbStep=1");
	GetOffAndOn(45.0f);
	g_camYaw = *head;
}

/* Riding beside a railing (test 42, new 1: a rail beside the bike, the heading a few degrees into
 * it, read as a wall or an obstacle ahead, and the speed went 897 -> 359 and 909 -> 31; plan S1).
 * Each plane a tall face (FakeWall, layer 1) whose line crosses the heading `cross` ahead of the
 * player, `deg` off it, the face on the left and facing the bike, the pick's normal written for
 * it; the capsule held at it and kept at g_capSlip of its motion along it (0.4 here: the game's
 * 850 -> 358 a trace line after the contact), and in the slides the speed by the game's curve
 * (g_gameCurve), so the Lead cap follows the speed down as it did in the game: without the hold
 * the fake reads 898 -> 752 -> 604 -> 342 -> 217 -> 162 a quarter second apart, test 42's 909 ->
 * 818 -> 481 -> 251 -> 110 -> 31. The checks: a face across the way is a wall as before; one at
 * 10 deg is alongside, left alone, and the slide along it held from the Lead cap for SlideHold;
 * SlideHold=0, FaceAlong=0, FaceAlongRays=0 and a normal of zeros each as the plan says. */
static FakePlane *g_alongW;
static float g_alongU[2];               /* the face's line, the way the bike goes along it */
static float g_alongLeast;              /* the least output speed (2 x the input) while the capsule was clear of it */
static float g_alongContact[2];         /* where the capsule first touched it */
static bool g_alongTouched;
/* The slide's timeline (AlongSlide), in the frames' own time so no read of the log falls between
 * the contact and the second after it (a read takes real time the fake doesn't ride, and the
 * plugin's measured speed dips for that frame; so does every RunFrames call's last sleep, a third
 * of the time in calls of 10 ms): from the contact, the camera turned 30 deg away from the face
 * at 0.6 s, the input and the cap's lines read at 0.8 s, how far along it at 1 s. */
static bool g_alongTimeline;
static float g_alongT, g_alongTc, g_alongInput08, g_alongWent;
static int g_alongCapped08, g_alongLinesAtContact;
static void AlongFrame(float dt)
{
	ClimbFrame(dt);
	if (!g_alongW || !g_alongW->on)
		return;
	g_alongT += dt;
	if (FaceGap(g_alongW) < CAPSULE_R + 0.5f) {
		if (!g_alongTouched) {
			g_alongTouched = true;
			g_alongTc = g_alongT;
			g_alongContact[0] = PlayerPos()[0];
			g_alongContact[1] = PlayerPos()[1];
			if (g_alongTimeline)
				g_alongLinesAtContact = LogLines("rays: a face alongside, 10 deg off the heading: ");   /* its time not ridden: the hold (if any) starts at once */
		}
	} else if (!g_alongTouched) {
		float out = 2.0f * hypotf(MoveInput()[0], MoveInput()[1]);
		if (out < g_alongLeast)
			g_alongLeast = out;
	}
	if (!g_alongTimeline || !g_alongTouched)
		return;
	float since = g_alongT - g_alongTc;
	if (since >= 0.6f && since - dt < 0.6f)
		g_camYaw = PlayerHeading() + 30.0f / DEG;   /* away from the face, on the left */
	if (since >= 0.8f && since - dt < 0.8f) {
		g_alongInput08 = hypotf(MoveInput()[0], MoveInput()[1]);
		g_alongCapped08 = LogLines("held to the measured speed");   /* the hold's second ends 1 s on (the plugin's clock); its read's time not ridden, harmless now */
	}
	if (since >= 1.0f && since - dt < 1.0f)
		g_alongWent = (PlayerPos()[0] - g_alongContact[0]) * g_alongU[0] + (PlayerPos()[1] - g_alongContact[1]) * g_alongU[1];
}
/* Plane i as above; halfWidth 0 (a face that goes on) or a post's; kind: the capsule's (CAP_NONE: the rays' alone). */
static FakePlane *AlongPlane(int i, float cross, float deg, float halfWidth, int kind)
{
	FakePlane *w = &g_planes[i];
	float h = PlayerHeading(), f[2] = { sinf(h), cosf(h) }, r[2] = { cosf(h), -sinf(h) }, sb = sinf(deg / DEG), cb = cosf(deg / DEG);
	memset(w, 0, sizeof(*w));
	w->point[0] = PlayerPos()[0] + f[0] * cross;
	w->point[1] = PlayerPos()[1] + f[1] * cross;
	w->normal[0] = -sb * f[0] + cb * r[0];   /* the face on the left: its normal points back and to the right */
	w->normal[1] = -sb * f[1] + cb * r[1];
	w->layer = 1;
	w->halfWidth = halfWidth;
	w->on = true;
	g_capKind[i] = kind;
	g_capDepth[i] = 400.0f;
	g_planeTopDepth[i] = 0.0f;
	g_capHeld = 0;
	g_alongU[0] = cb * f[0] + sb * r[0];
	g_alongU[1] = cb * f[1] + sb * r[1];
	g_alongW = w;
	g_alongTouched = false;
	g_alongLeast = 9.0f;
	return w;
}
static float AlongAhead(const FakePlane *w)   /* the player's axis to the face's line along the heading */
{
	float h = PlayerHeading(), c = -(w->normal[0] * sinf(h) + w->normal[1] * cosf(h));
	return c > 0.01f ? FaceGap(w) / c : 1e9f;
}
static void AlongClear(void)
{
	ClearObstacles();
	g_alongW = NULL;
}
static float AlongStill(void)   /* moved in a quarter second */
{
	float p0[2];
	Mark(p0);
	RunFrames(250);
	return Moved(p0);
}
static int AlongVerdicts(void)   /* the face rays' lines for a wall or an obstacle ahead */
{
	return LogLines("rays: a wall ahead (") + LogLines("an obstacle ahead (") + LogLines("an obstacle lower than 1.5 wheel radii ahead (");
}
/* On afresh, W held from rest for ms (3.5 s: the top, 900). */
static void AlongOn(int ms)
{
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	Keys(0.0f, 1.0f);
	RunFrames(ms);
}
/* The 10 deg face placed 325 ahead (the bike at 900) and W held 1.5 s (the contact 0.25 s on), the
 * camera turned 30 deg away from it 0.6 s after the contact (AlongFrame's timeline). Returns how far
 * along the face's line the bike went in the second after the contact (-1: no contact), with the
 * input the plugin wrote 0.8 s after it (past the cap's fall, before the hold's end), the "held to
 * the measured speed" lines by then and the alongside lines by the contact. The log is read
 * before the face is placed and 0.4 s ridden after, the plugin's measured speed back from the
 * reads' dip (by a fifth with the log this long: under 0.8 of the top it binds the cap). */
static float AlongSlide(float *input, int *capped, int *alongBefore)
{
	int along0 = LogLines("rays: a face alongside, 10 deg off the heading: "), cap0 = LogLines("held to the measured speed");
	RunFrames(400);
	AlongPlane(0, 325.0f, 10.0f, 0.0f, CAP_STEP);
	g_alongT = 0.0f;
	g_alongInput08 = -1.0f;
	g_alongCapped08 = cap0;
	g_alongLinesAtContact = along0;
	g_alongWent = -1.0f;
	g_alongTimeline = true;
	RunFrames(1500);
	g_alongTimeline = false;
	*alongBefore = g_alongLinesAtContact - along0;
	*input = g_alongInput08;
	*capped = g_alongCapped08 - cap0;
	return g_alongTouched && g_alongT - g_alongTc >= 1.0f ? g_alongWent : -1.0f;
}

static void AlongTests(void)
{
	float moved, ahead;
	g_onFrame = AlongFrame;
	g_capSlip = 0.4f;

	printf("railing (test 42, new 1): FaceAlong 30 with the rays either side, SlideHold 1 s; a tall face whose line crosses the heading 400 ahead at 60 deg (across the way), W held from rest 3.5 s: a wall, stopped short of it as before, the ride's normal line \"usable\":\n");
	{
		AlongOn(0);
		CHECK(LogLines("a face whose line lies under 30 deg off the heading by the pick's hit normal is alongside and left alone (FaceAlong), if two rays at axle height either side confirm it") >= 1 &&
		      LogLines("the throttle held at what it was for up to 1 s instead of capped to the measured speed (SlideHold)") >= 1,
		      "the steer settings line names FaceAlong 30 with the rays (FaceAlongRays=1) and SlideHold 1 s");
		RunFrames(3500);
		int wall0 = LogLines("rays: a wall ahead ("), along0 = LogLines("a face alongside"), slide0 = LogLines("slide: "), normal0 = LogLines("rays: the pick's hit normal at the first face (");
		int usable0 = LogLines("length 1.000, 60 deg off the heading, the rays' slope 90: usable");
		FakePlane *w = AlongPlane(0, 400.0f, 60.0f, 0.0f, CAP_STEP);
		RunFrames(2500);
		moved = AlongStill();
		ahead = AlongAhead(w);
		CHECK(LogLines("rays: a wall ahead (") > wall0 && LogLines("a face alongside") == along0 && LogLines("slide: ") == slide0 && ahead > 100.0f && ahead < 220.0f && moved < 5.0f,
		      "a \"wall ahead\" line (%d), no alongside or slide line, stopped (%.1f in 0.25 s) %.0f from its line along the heading (the front wheel's edge 130 ahead)",
		      LogLines("rays: a wall ahead (") - wall0, moved, ahead);
		CHECK(LogLines("rays: the pick's hit normal at the first face (") - normal0 == 1 && LogLines("length 1.000, 60 deg off the heading, the rays' slope 90: usable") - usable0 == 1,
		      "one \"the pick's hit normal at the first face (...), length 1.000, 60 deg off the heading, the rays' slope 90: usable\" line (%d)", LogLines("rays: the pick's hit normal at the first face (") - normal0);

		printf("railing: on in the same ride, 2.5 s more W, a face at 40 deg 400 ahead: a wall, no hold, stopped short as before:\n");
		AlongClear();
		RunFrames(2500);
		wall0 = LogLines("rays: a wall ahead (");
		along0 = LogLines("a face alongside");
		slide0 = LogLines("slide: ");
		w = AlongPlane(0, 400.0f, 40.0f, 0.0f, CAP_STEP);
		RunFrames(2500);
		moved = AlongStill();
		ahead = AlongAhead(w);
		CHECK(LogLines("rays: a wall ahead (") > wall0 && LogLines("a face alongside") == along0 && LogLines("slide: ") == slide0 && ahead > 100.0f && ahead < 220.0f && moved < 5.0f && !g_alongTouched,
		      "a \"wall ahead\" line (%d), no alongside or slide line, stopped (%.1f in 0.25 s) %.0f from its line along the heading, the capsule clear of it",
		      LogLines("rays: a wall ahead (") - wall0, moved, ahead);

		printf("railing: on again, a post 20 wide 500 ahead whose normal reads 15 deg off the heading (a trunk grazed): the rays either side miss it, across: a wall, stopped short:\n");
		AlongClear();
		RunFrames(2500);
		wall0 = LogLines("rays: a wall ahead (");
		along0 = LogLines("a face alongside");
		int note0 = LogLines("(alongside by its normal, 15 deg off the heading, but the rays either side don't say so: toward it found nothing within ");
		w = AlongPlane(0, 500.0f, 15.0f, 10.0f, CAP_NONE);
		RunFrames(2500);
		moved = AlongStill();
		ahead = FaceGap(w) >= 0.0f ? hypotf(PlayerPos()[0] - w->point[0], PlayerPos()[1] - w->point[1]) : -1.0f;
		CHECK(LogLines("rays: a wall ahead (") > wall0 && LogLines("a face alongside") == along0 && moved < 5.0f && ahead > 100.0f && ahead < 220.0f,
		      "a \"wall ahead\" line (%d), no alongside line, stopped (%.1f in 0.25 s) %.0f from the post", LogLines("rays: a wall ahead (") - wall0, moved, ahead);
		CHECK(LogLines("(alongside by its normal, 15 deg off the heading, but the rays either side don't say so: toward it found nothing within ") > note0,
		      "the wall line says \"alongside by its normal, 15 deg off the heading, but the rays either side don't say so: toward it found nothing within ...\" (%d)",
		      LogLines("(alongside by its normal, 15 deg off the heading, but the rays either side don't say so: toward it found nothing within ") - note0);
		Keys(0.0f, 0.0f);
		AlongClear();
	}

	printf("railing: a tall face whose line crosses the heading 325 ahead, 10 deg off it, on the left, at 900 (the speed by the game's curve): alongside (no wall or obstacle line), the input full to the contact; the capsule slides along it at 0.4 of its motion; SlideHold 1: held, 300 or more along it in the second after the contact, the camera turned 30 deg away 0.6 s on:\n");
	{
		g_gameCurve = true;
		AlongOn(3500);
		int verdicts0 = AlongVerdicts(), start0 = LogLines("slide: along a face 10 deg off the heading (FakeWall, layer 1, seen "), over0 = LogLines("slide: over after "), boost0 = LogLines("the climb limit 47 -> 85");
		int capped, alongBefore;
		float input, went = AlongSlide(&input, &capped, &alongBefore);
		CHECK(went > -1.0f && AlongVerdicts() == verdicts0 && alongBefore == 1 && g_alongLeast >= 1.99f,
		      "touched it (%s), no wall or obstacle line (%d), one \"a face alongside, 10 deg off the heading\" line before the contact (%d), the input full to it (the output %.2f at the least)",
		      went > -1.0f ? "yes" : "no", AlongVerdicts() - verdicts0, alongBefore, g_alongLeast);
		CHECK(went >= 300.0f && capped == 0 && input >= 0.99f, "%.0f along it in the second after the contact, the input %.2f 0.8 s on, no \"held to the measured speed\" by then (%d)", went, input, capped);
		RunFrames(500);
		CHECK(LogLines("slide: along a face 10 deg off the heading (FakeWall, layer 1, seen ") - start0 == 1 && LogLines("slide: over after ") - over0 == 1 && LogLines("the climb limit 47 -> 85") == boost0,
		      "one \"slide: along a face 10 deg off the heading (FakeWall, layer 1, seen ...\" line (%d), one \"slide: over after\" (%d), no climb boost",
		      LogLines("slide: along a face 10 deg off the heading (FakeWall, layer 1, seen ") - start0, LogLines("slide: over after ") - over0);
		Keys(0.0f, 0.0f);
		AlongClear();
		float slid = went;

		printf("railing: SlideHold=0 written (read again on getting on), the same slide: the Lead cap follows the speed down as in test 42's build, no slide line:\n");
		RewriteIni("SlideHold=1.0", "SlideHold=0");
		AlongOn(3500);
		CHECK(LogLines("no hold on the throttle while sliding along a face (SlideHold=0)") >= 1, "the settings line says SlideHold=0");
		int slide0 = LogLines("slide: ");
		went = AlongSlide(&input, &capped, &alongBefore);
		RunFrames(500);
		CHECK(went > -1.0f && capped >= 2 && input < 0.8f && went < 0.65f * slid && LogLines("slide: ") == slide0,
		      "%.0f along it in the second (under 0.65 of the %.0f held), the input %.2f 0.8 s on, %d \"held to the measured speed\" lines by then, no slide line", went, slid, input, capped);
		Keys(0.0f, 0.0f);
		AlongClear();
		RewriteIni("SlideHold=0", "SlideHold=1.0");
		g_gameCurve = false;
	}

	printf("railing: FaceAlong=0 written: the 10 deg face judged by its steepness alone, a wall, stopped short of it as in test 42's build:\n");
	{
		RewriteIni("FaceAlong=30", "FaceAlong=0");
		AlongOn(3500);
		CHECK(LogLines("every face judged by its steepness alone (FaceAlong=0)") >= 1, "the settings line says FaceAlong=0");
		int wall0 = LogLines("rays: a wall ahead (90 deg): "), along0 = LogLines("a face alongside"), slide0 = LogLines("slide: ");
		AlongPlane(0, 325.0f, 10.0f, 0.0f, CAP_STEP);
		RunFrames(2500);
		moved = AlongStill();
		CHECK(LogLines("rays: a wall ahead (90 deg): ") > wall0 && LogLines("a face alongside") == along0 && LogLines("slide: ") == slide0 && moved < 5.0f && !g_alongTouched,
		      "a \"wall ahead (90 deg)\" line (%d), no alongside or slide line, stopped (%.1f in 0.25 s) short of it (the capsule %s)", LogLines("rays: a wall ahead (90 deg): ") - wall0, moved,
		      g_alongTouched ? "touched it" : "clear of it");
		Keys(0.0f, 0.0f);
		AlongClear();
		RewriteIni("FaceAlong=0", "FaceAlong=30");
	}

	printf("railing: FaceAlongRays=0 written: the post read by its normal alone, alongside:\n");
	{
		RewriteIni("FaceAlongRays=1", "FaceAlongRays=0");
		AlongOn(2500);
		CHECK(LogLines("by the normal alone (FaceAlongRays=0)") >= 1, "the settings line says FaceAlongRays=0");
		int along0 = LogLines("rays: a face alongside, 15 deg off the heading: ");
		AlongPlane(0, 500.0f, 15.0f, 10.0f, CAP_NONE);
		RunFrames(600);
		CHECK(LogLines("rays: a face alongside, 15 deg off the heading: ") > along0, "a \"face alongside, 15 deg off the heading\" line (%d)", LogLines("rays: a face alongside, 15 deg off the heading: ") - along0);
		Keys(0.0f, 0.0f);
		AlongClear();
		RewriteIni("FaceAlongRays=0", "FaceAlongRays=1");
	}

	printf("railing: the pick's normal zeros on every hit (a game that doesn't fill it): the ride's normal line says so once, the 10 deg face a wall as in test 42's build:\n");
	{
		g_fakeNormalBad = true;
		AlongOn(3500);
		int bad0 = LogLines("rays: the pick's hit normal at the first face (0.000, 0.000, 0.000), length 0.000, "), notUnit0 = LogLines(": not a unit vector: faces judged by their steepness alone");
		int wall0 = LogLines("rays: a wall ahead (90 deg): "), along0 = LogLines("a face alongside");
		AlongPlane(0, 325.0f, 10.0f, 0.0f, CAP_STEP);
		RunFrames(2500);
		moved = AlongStill();
		CHECK(LogLines("rays: the pick's hit normal at the first face (0.000, 0.000, 0.000), length 0.000, ") - bad0 == 1 && LogLines(": not a unit vector: faces judged by their steepness alone") - notUnit0 == 1,
		      "one \"the pick's hit normal at the first face (0.000, 0.000, 0.000), length 0.000, ...: not a unit vector: faces judged by their steepness alone\" line (%d)",
		      LogLines(": not a unit vector: faces judged by their steepness alone") - notUnit0);
		CHECK(LogLines("rays: a wall ahead (90 deg): ") > wall0 && LogLines("a face alongside") == along0 && moved < 5.0f && !g_alongTouched,
		      "a \"wall ahead (90 deg)\" line (%d), no alongside line, stopped (%.1f in 0.25 s) short of it", LogLines("rays: a wall ahead (90 deg): ") - wall0, moved);
		g_fakeNormalBad = false;
		Keys(0.0f, 0.0f);
		AlongClear();
	}

	/* CLIMB_ALONG (review of test 43's build: the slide's "no climb boost" can't fail, its tall
	 * face refused as something at ClimbTop first): a step 15 high across the way 150 ahead,
	 * under ClimbTop and the axle ray, and a tall face 12 deg off the heading whose line crosses
	 * the heading 259 ahead, 127 past the axis once the capsule is held at the step: within the
	 * face rays' reach at rest (the front wheel's edge 129.5, and 5), and past the end of the
	 * stall's ray at ClimbTop 12 to the left (63 long, the face 70 along it; 59 at 10 deg, which
	 * would make that line's word "something at 31.9"). */
	printf("railing: a step 15 high across the way 150 ahead and a tall face 12 deg off the heading whose line crosses it 259 ahead (127 past the axis at the step), W held from rest: no boost, held at the step, \"not climbed: a face alongside\":\n");
	{
		AlongOn(0);
		int boost0 = LogLines("the climb limit 47 -> 85"), along0 = LogLines("not climbed: a face alongside, 12 deg off the heading (FakeWall, layer 1, the face rays' verdict)");
		AlongPlane(0, 259.0f, 12.0f, 0.0f, CAP_STEP);
		FakePlane *step = Obstacle(1, 150.0f, 15.0f, CAP_STEP, 60.0f, 1, NULL);
		RunFrames(3000);
		CHECK(LogLines("the climb limit 47 -> 85") == boost0 && FaceGap(step) > 17.0f && FaceGap(step) < 19.0f && !g_alongTouched,
		      "no \"the climb limit 47 -> 85\" line (%d), held at the step (the axis %.1f from its face), the capsule clear of the tall face", LogLines("the climb limit 47 -> 85") - boost0, FaceGap(step));
		CHECK(LogLines("not climbed: a face alongside, 12 deg off the heading (FakeWall, layer 1, the face rays' verdict)") - along0 == 1,
		      "one \"climb: stopped with forward held (...): not climbed: a face alongside, 12 deg off the heading (FakeWall, layer 1, the face rays' verdict)\" line (%d)",
		      LogLines("not climbed: a face alongside, 12 deg off the heading (FakeWall, layer 1, the face rays' verdict)") - along0);
		Keys(0.0f, 0.0f);
		AlongClear();
	}
	Keys(0.0f, 0.0f);
	RunFrames(2500);
	g_capSlip = 1.0f;
	g_onFrame = ClimbFrame;
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
}

/* Test 44's rails (the note's 2: a wooden road barrier and a guard rail round a brush pile
 * climbed, the bike hung astride them): ClimbMaxTop=18, the default, rewritten from the 0 the
 * checks above ride with. A rail 27 high 400 ahead, its top 10 deep for the rays down and the
 * ground behind it as in front: no boost, held at it, one "a beam with a drop behind it" line.
 * A step 25 high whose top goes on 400 (the ground at its height a wheelbase past the face): the
 * boost as with ClimbMaxTop=0, stepped up onto it (stage 2), over it. Test 45's review: the same
 * step on a 4 deg slope up to it and down to it (the ground at the face's foot, not a line
 * stretched from the rear wheel), round logs 25 and 30 across and a stump 25 high and 30 across
 * (test 42: "trunks, stumps ok") climbed, and a barrier's low foot with its bar beyond (test
 * 44's 22:47:39) not. Each on a ride of its own (the climb's hand full at its start). */
static void RailTests(void)
{
	float cos85 = cosf(85.0f / DEG);
	static const char beamWords[] = "not climbed: a beam with a drop behind it, not a step up: something at 18 above the feet ";
	static const char stepWord[] = "ahead: a step up, the ground ";
	static const char longWords[] = "ahead (FakeWall, layer 1; ClimbMaxTop), not round (90 deg at its foot) and long (the rays 36 to either side meet it too, cast at 18 and 24 (NarrowHeights)), and a wheelbase on, ";
	static const char footWords[] = " ahead, the ground 0.0 over the ground at its foot (FakeGround, layer 13)";
	RewriteIni("ClimbMaxTop=0", "ClimbMaxTop=18");
	printf("rails (test 44): ClimbMaxTop=18 rewritten, off and on again; a rail 27 high 400 ahead (its top 10 deep, the ground behind it as in front), W held 4 s: no boost, held at it, one \"a beam with a drop behind it\" line:\n");
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	CHECK(LogLines("a face with something 18 above the feet within 45 past it climbed only if round (receding toward its foot), narrow (rays two capsule radii to a side pass it at 18, 6 over it and the face's top less 4, "
	               "each where it is within the face (NarrowHeights=3)) or a step up (a ray down a wheelbase past it finds the ground that high over the ground at its foot) "
	               "(ClimbMaxTop: a log, a stump or a step, not a rail or a beam with a drop behind it), and a low face with something 1.5 or 2 ClimbTops above the feet within 45 past it not climbed (a barrier's bar); "
	               "a lower face, its top 8 or more over its foot, not climbed either if upright (80 to 100 deg at its foot and at its top), long (not narrow at 10 and its top less 2) and thin (the ground two capsule radii "
	               "past its face under half its top over its foot): a rail lying on the ground (ClimbBeamLow), a kerb, a step, a log or a stump still climbed; a sharp step the limit can't take stepped up onto (ClimbStep=1)") == 1,
	      "the climb's settings line again: ClimbMaxTop 18, a log, a stump or a step, not a rail or a beam, nor a barrier's bar; NarrowHeights 3; ClimbBeamLow 8");
	{
		int low0 = LogLines("climb: a low face at the capsule"), beam0 = LogLines(beamWords), far0 = LogLines("), and a wheelbase on, "), sets0 = g_setPositions;
		int long0 = LogLines(longWords), foot0 = LogLines(footWords);
		g_slopeMin = 1.0f;
		FakePlane *w = Obstacle(0, 400.0f, 27.0f, CAP_STEP, 10.0f, 1, NULL);
		g_planeTopDepth[0] = 10.0f;
		float passed = RideAt(w, 10.0f, 4000);
		CHECK(passed < 0.0f && FaceGap(w) > 17.0f && g_setPositions == sets0 && Near(g_slopeMin, COS47) && LogLines("climb: a low face at the capsule") == low0,
		      "held at it (the axis %.1f from its face), the limit 47 throughout (the steepest %.2f deg), no boost (%d line), no step up (%d)", FaceGap(w), acosf(g_slopeMin) * DEG,
		      LogLines("climb: a low face at the capsule") - low0, g_setPositions - sets0);
		CHECK(LogLines(beamWords) - beam0 == 1 && LogLines("), and a wheelbase on, ") - far0 == 1 && LogLines(longWords) - long0 == 1 && LogLines(footWords) - foot0 == 1,
		      "one \"climb: stopped with forward held (...): not climbed: a beam with a drop behind it, not a step up: something at 18 above the feet ... %s...%s\" line (%d, %d, %d, %d)", longWords, footWords,
		      LogLines(beamWords) - beam0, LogLines("), and a wheelbase on, ") - far0, LogLines(longWords) - long0, LogLines(footWords) - foot0);
		RollOff();
	}

	printf("rails (test 44): ClimbMaxTop=18, a step 25 high 400 ahead whose top goes on 400 (the ground at its height a wheelbase past the face), SetPosition honoured, W held: the boost on, stepped up onto it, over it, as with ClimbMaxTop=0:\n");
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	{
		int low0 = LogLines("climb: a low face at the capsule"), beam0 = LogLines(beamWords), step0 = LogLines("climb: stepped up 26.5 (the top 25.0 at "), over0 = LogLines("climb: over it after");
		int word0 = LogLines("ahead: a step up, the ground 25.0 over the ground at its foot ");
		g_slopeMin = 1.0f;
		FakePlane *w = Obstacle(0, 400.0f, 25.0f, CAP_STEP, 400.0f, 1, NULL);
		g_planeTopDepth[0] = 400.0f;
		float took = UntilBoost(cos85, 3000);
		RunFrames(600);
		float lift = g_feetLift;
		RunFrames(600);
		CHECK(took > 0.0f && LogLines("climb: a low face at the capsule") - low0 == 1 && LogLines(beamWords) == beam0 && LogLines("ahead: a step up, the ground 25.0 over the ground at its foot ") - word0 == 1,
		      "the boost on at the step (%.2f s), one \"low face\" line saying \"...; at 18 ... ahead: a step up, the ground 25.0 over the ground at its foot ... (ClimbMaxTop)\" (%d), no beam line", took,
		      LogLines("ahead: a step up, the ground 25.0 over the ground at its foot ") - word0);
		CHECK(LogLines("climb: stepped up 26.5 (the top 25.0 at ") - step0 >= 1 && lift > 24.5f && LogLines("climb: over it after") - over0 == 1 && FaceGap(w) < -20.0f,
		      "stepped up onto it (%d \"stepped up 26.5 (the top 25.0 at ...\" line(s)), the feet %.1f over the ground 0.6 s after the boost, \"over it\" (%d), the axis %.0f past the face",
		      LogLines("climb: stepped up 26.5 (the top 25.0 at ") - step0, lift, LogLines("climb: over it after") - over0, -FaceGap(w));
		RollOff();
	}

	/* Test 45's review: on a slope of a few degrees the line stretched from the rear wheel's ray
	 * 158 ahead put a step's level top under 18 uphill (refused past 2.9 deg for a 25 step) and
	 * started the ray down inside it downhill. The slope rises (or falls) 4 deg along the
	 * heading to the step's foot, its top level at 25 over that foot. */
	for (int k = 0; k < 2; k++) {
		printf("rails (test 45's review): ClimbMaxTop=18, the same step 25 high 400 ahead, its top level and 400 deep, on a 4 deg slope %s to it, SetPosition honoured, W held: the boost on, stepped up onto it, over it, as on the flat:\n",
		       k ? "down" : "up");
		GetOffAndOn(45.0f);
		g_camYaw = PlayerHeading();
		float h = PlayerHeading(), fx = sinf(h), fy = cosf(h), feet = PlayerPos()[2], sk = tanf((k ? -4.0f : 4.0f) / DEG);
		int low0 = LogLines("climb: a low face at the capsule"), beam0 = LogLines(beamWords), word0 = LogLines(stepWord), step0 = LogLines("climb: stepped up "), over0 = LogLines("climb: over it after");
		FakePlane *w = Obstacle(0, 400.0f, 25.0f, CAP_STEP, 400.0f, 1, NULL);
		g_planeTopDepth[0] = 400.0f;
		g_slopeK = sk;   /* the ground along the heading, the step's foot on its line */
		g_slopeD[0] = fx;
		g_slopeD[1] = fy;
		g_slopeO[0] = w->point[0];
		g_slopeO[1] = w->point[1];
		g_groundZ = feet + 400.0f * sk;
		float lean[3] = { k ? fx : -fx, k ? fy : -fy, 0.0f };   /* the normal leans back uphill, ahead downhill */
		SetNormalTowards(lean, 4.0f);
		float took = UntilBoost(cos85, 3000);
		float said = LastLogNumber(stepWord);
		RunFrames(600);
		float lift = g_feetLift;
		RunFrames(600);
		CHECK(took > 0.0f && LogLines("climb: a low face at the capsule") - low0 == 1 && LogLines(beamWords) == beam0 && LogLines(stepWord) - word0 == 1 && fabsf(said - 25.0f) < 0.5f,
		      "the boost on at the step (%.2f s), one \"low face\" line saying \"a step up, the ground %.1f over the ground at its foot\" (%d), no beam line", took, said, LogLines(stepWord) - word0);
		CHECK(LogLines("climb: stepped up ") - step0 >= 1 && lift > 24.5f && LogLines("climb: over it after") - over0 == 1 && FaceGap(w) < -20.0f,
		      "stepped up onto it (%d \"stepped up\" line(s)), the feet %.1f over the ground 0.6 s after the boost, \"over it\" (%d), the axis %.0f past the face",
		      LogLines("climb: stepped up ") - step0, lift, LogLines("climb: over it after") - over0, -FaceGap(w));
		Keys(0.0f, 0.0f);
		ClearObstacles();
		SetNormal(0.0f, 0.0f, 1.0f);
		FlatGround();
		RunFrames(2500);
	}

	/* Round logs (the rays see a circle: the ray at 4 meets it 3.1 to 3.9 further on than the one
	 * at 10, the face 117 to 123 deg at its foot), the ground behind them as in front: climbed. */
	for (int k = 0; k < 2; k++) {
		float T = k ? 30.0f : 25.0f;
		printf("rails (test 45's review): ClimbMaxTop=18, a round log %.0f across 600 ahead (its face receding toward its foot, the ground behind it as in front), W held: the boost on, over it, as with ClimbMaxTop=0 (test 42: \"trunks, stumps ok\"):\n", T);
		GetOffAndOn(45.0f);
		g_camYaw = PlayerHeading();
		int low0 = LogLines("climb: a low face at the capsule"), beam0 = LogLines(beamWords), round0 = LogLines("ahead: round, receding toward its foot (ClimbMaxTop)"), over0 = LogLines("climb: over it after");
		g_slopeMin = 1.0f;
		FakePlane *w = Obstacle(0, 600.0f, T, CAP_LOG, T, 1, NULL);
		w->round = true;
		float passed = RideAt(w, T, 3000);
		float steepest = g_slopeMin;
		RunFrames(500);
		CHECK(passed > 0.0f && Near(steepest, cos85) && LogLines("climb: a low face at the capsule") - low0 == 1 && LogLines("climb: over it after") - over0 == 1,
		      "over it within 3 s (%.2f s), the limit at 85 (the steepest %.2f deg), one \"low face\" and one \"over it\" line (%d, %d)", passed, acosf(steepest) * DEG,
		      LogLines("climb: a low face at the capsule") - low0, LogLines("climb: over it after") - over0);
		CHECK(LogLines("ahead: round, receding toward its foot (ClimbMaxTop)") - round0 == 1 && LogLines(beamWords) == beam0,
		      "the low face line says \"...; at 18 ... ahead: round, receding toward its foot (ClimbMaxTop)\" (%d), no beam line", LogLines("ahead: round, receding toward its foot (ClimbMaxTop)") - round0);
		RollOff();
	}

	/* A stump: sharp, 25 high, 30 across (halfWidth 15), its top 30 deep, the ground behind it as
	 * in front; the side rays 36 off the line pass it. */
	printf("rails (test 45's review): ClimbMaxTop=18, a stump 25 high and 30 across 400 ahead (sharp, its top 30 deep, the ground behind it as in front), SetPosition honoured, W held: the boost on (the rays 36 to the sides pass it), stepped up onto it, over it:\n");
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	{
		int low0 = LogLines("climb: a low face at the capsule"), beam0 = LogLines(beamWords), narrow0 = LogLines("ahead: narrow, the rays 36 to either side across its face pass it"), step0 = LogLines("climb: stepped up 26.5 (the top 25.0 at ");
		FakePlane *w = Obstacle(0, 400.0f, 25.0f, CAP_STEP, 30.0f, 1, NULL);
		w->halfWidth = 15.0f;
		g_planeTopDepth[0] = 30.0f;
		float passed = RideAt(w, 30.0f, 4000);
		CHECK(passed > 0.0f && LogLines("climb: a low face at the capsule") - low0 >= 1 && LogLines("ahead: narrow, the rays 36 to either side across its face pass it") - narrow0 >= 1 && LogLines(beamWords) == beam0,
		      "over it within 4 s (%.2f s), the low face line saying \"...; at 18 ... ahead: narrow, the rays 36 to either side across its face pass it ... (ClimbMaxTop, ..., NarrowBoth)\" (%d; test 46's rails: both sides), no beam line", passed,
		      LogLines("ahead: narrow, the rays 36 to either side across its face pass it") - narrow0);
		CHECK(LogLines("climb: stepped up 26.5 (the top 25.0 at ") - step0 >= 1, "stepped up onto it (%d \"stepped up 26.5 (the top 25.0 at ...\" line(s))", LogLines("climb: stepped up 26.5 (the top 25.0 at ") - step0);
		RollOff();
	}

	/* Test 44's barrier at 22:47:39 (0000DD7E_Physics, "the front hit 65 above the feet"): a low
	 * foot at the capsule and a bar beyond it over ClimbTop, which neither the ray at 18 nor the
	 * one at 31.9 meets: the bar ray at 47.9 does. */
	static const char barWords[] = "not climbed: a bar beyond the low face: something at 48 above the feet 43 ahead (FakeWall, layer 1; ClimbMaxTop), where the capsule would hang on the face under it (a barrier)";
	printf("rails (test 45's review): ClimbMaxTop=18, a barrier 400 ahead: a foot 8 high and 10 deep, and 25 past its face a bar from 40 to 65 over the ground, W held 4 s: no boost, held at the foot, one \"a bar beyond the low face\" line:\n");
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	{
		int low0 = LogLines("climb: a low face at the capsule"), bar0 = LogLines(barWords), sets0 = g_setPositions;
		g_slopeMin = 1.0f;
		FakePlane *foot = Obstacle(0, 400.0f, 8.0f, CAP_STEP, 10.0f, 1, NULL);
		FakePlane *bar = Obstacle(1, 425.0f, 65.0f, CAP_STEP, 10.0f, 1, NULL);
		bar->bottom = 40.0f;
		g_planeTopDepth[0] = g_planeTopDepth[1] = 10.0f;
		float passed = RideAt(foot, 10.0f, 4000);
		CHECK(passed < 0.0f && FaceGap(foot) > 17.0f && g_setPositions == sets0 && Near(g_slopeMin, COS47) && LogLines("climb: a low face at the capsule") == low0,
		      "held at the foot (the axis %.1f from its face), the limit 47 throughout (the steepest %.2f deg), no boost (%d line), no step up (%d)", FaceGap(foot), acosf(g_slopeMin) * DEG,
		      LogLines("climb: a low face at the capsule") - low0, g_setPositions - sets0);
		CHECK(LogLines(barWords) - bar0 == 1, "one \"climb: stopped with forward held (...): %s\" line (%d)", barWords, LogLines(barWords) - bar0);
		RollOff();
	}
	RewriteIni("ClimbMaxTop=18", "ClimbMaxTop=0");
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	printf("rails (test 45's review): ClimbMaxTop=0 again (read again on getting on), the same barrier, W held: the boost on at its foot, as in test 44's build:\n");
	{
		int bar0 = LogLines("not climbed: a bar beyond the low face");
		Obstacle(0, 400.0f, 8.0f, CAP_STEP, 10.0f, 1, NULL);
		FakePlane *bar = Obstacle(1, 425.0f, 65.0f, CAP_STEP, 10.0f, 1, NULL);
		bar->bottom = 40.0f;
		g_planeTopDepth[0] = g_planeTopDepth[1] = 10.0f;
		float took = UntilBoost(cos85, 3000);
		CHECK(took > 0.0f && LogLines("not climbed: a bar beyond the low face") == bar0, "the boost on at the foot (%.2f s), no bar line", took);
		RollOff();
	}
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
}

/* The number right after `after` on the line holding it the (skip + 1)-th time in the log (NAN:
 * no such line yet, or no number there): the first of a kind after a count taken before. */
static float NthLogNumber(const char *after, int skip)
{
	static char line[4096];
	FILE *f = OpenLog();
	if (!f)
		return NAN;
	float value = NAN;
	size_t len = strlen(after);
	while (fgets(line, sizeof(line), f)) {
		const char *at = strstr(line, after);
		if (!at || skip-- > 0)
			continue;
		char *end;
		float v = strtof(at + len, &end);
		if (end != at + len)
			value = v;
		break;
	}
	fclose(f);
	return value;
}

/* Whether the line holding `text` the (skip + 1)-th time also holds `also`. */
static bool NthLogLineHas(const char *text, int skip, const char *also)
{
	static char line[4096];
	FILE *f = OpenLog();
	if (!f)
		return false;
	bool has = false;
	while (fgets(line, sizeof(line), f)) {
		if (!strstr(line, text) || skip-- > 0)
			continue;
		has = strstr(line, also) != NULL;
		break;
	}
	fclose(f);
	return has;
}

/* Test 45's rail met square at 905 (WallStop): the front wheel's edge (129.5 ahead of the axis)
 * to the rail, the least since it was placed (+ short of it). */
static FakePlane *g_stopW;
static float g_stopLeast;
static void StopFrame(float dt)
{
	ClimbFrame(dt);
	if (g_stopW && g_stopW->on) {
		float gap = FaceGap(g_stopW) - (99.6f + 29.9f);
		if (gap < g_stopLeast)
			g_stopLeast = gap;
	}
}

/* Plane i turned deg about its point (the face's line deg off square to the heading, its far
 * end to the right for deg > 0). */
static void TurnPlane(FakePlane *w, float deg)
{
	float h = PlayerHeading(), f[2] = { sinf(h), cosf(h) }, r[2] = { cosf(h), -sinf(h) }, c = cosf(deg / DEG), s = sinf(deg / DEG);
	w->normal[0] = -f[0] * c + r[0] * s;
	w->normal[1] = -f[1] * c + r[1] * s;
}

/* Test 46's glimpses (WallStop cut the throttle 81 times in 857 s, mostly for things the bike was
 * steering past): the keys of test 47 at their defaults (on) or their off values (test 46's
 * build). WallStopNear isn't among them: since the review of test 47's build its default is its
 * off value, 0. */
static void GlimpseKeys(bool on)
{
	static const char *const keys[4][2] = { { "WallStopReach=1", "WallStopReach=0" }, { "WallStopPersist=0.15", "WallStopPersist=0" },
	                                        { "WallStopArc=90", "WallStopArc=0" }, { "WallStopShort=10", "WallStopShort=0" } };
	for (int i = 0; i < 4; i++)
		RewriteIni(keys[i][on ? 1 : 0], keys[i][on ? 0 : 1]);
}

/* The input's least size (1: full) from when a glimpse's plane went on, and its plane taken away
 * GlimpseFor after (frames' own time; 0: left), the least tracked till Watch after it went on;
 * the camera (and so the heading) turned at g_glimpseTurn (rad/s, + right) meanwhile if set. */
static FakePlane *g_glimpseW;
static float g_glimpseT, g_glimpseFor, g_glimpseWatch, g_glimpseLeast, g_glimpseTurn;
static void GlimpseFrame(float dt)
{
	StopFrame(dt);
	g_camYaw += g_glimpseTurn * dt;
	if (!g_glimpseW)
		return;
	if (g_glimpseT <= g_glimpseWatch) {
		float in = hypotf(MoveInput()[0], MoveInput()[1]);
		if (in < g_glimpseLeast)
			g_glimpseLeast = in;
	}
	g_glimpseT += dt;
	if (g_glimpseFor > 0.0f && g_glimpseT >= g_glimpseFor)
		g_glimpseW->on = false;
}
static void GlimpseWatch(FakePlane *w, float forSeconds, float watch)
{
	g_glimpseW = w;
	g_glimpseT = 0.0f;
	g_glimpseFor = forSeconds;
	g_glimpseWatch = watch;
	g_glimpseLeast = 9.0f;
}
/* On again and up to 900 along the heading (or the speed cap), W held, the game's run-down 1500
 * a second a second as for test 45's rail. */
static void UpToSpeed(float cap)
{
	g_onFrame = GlimpseFrame;
	g_glimpseW = NULL;
	g_glimpseTurn = 0.0f;
	g_topCap = cap;
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	Keys(0.0f, 1.0f);
	RunFrames(3500);
	g_fakeDecel = 1500.0f;
	g_fakeAccel = 400.0f;
}
static void DoneRiding(void)
{
	Keys(0.0f, 0.0f);
	g_stopW = g_glimpseW = NULL;
	g_glimpseTurn = 0.0f;
	g_fakeDecel = g_fakeAccel = 0.0f;
	g_topCap = 0.0f;
	ClearObstacles();
	RunFrames(1000);   /* 2500 till the review of test 47's build: the next UpToSpeed gets off and on anyway (climb's mode was near its 600 s) */
}
/* A raised rail (from 20 to 60 over the ground: both face rays meet it) `ahead` of the axis. */
static FakePlane *RaisedRail(float ahead, float halfWidth)
{
	FakePlane *w = Obstacle(0, ahead, 60.0f, CAP_NONE, 10.0f, 1, NULL);
	w->bottom = 20.0f;
	w->halfWidth = halfWidth;
	g_stopW = w;
	g_stopLeast = 1e9f;
	return w;
}

/* Test 46's WallStop (the note's 2): the longer rays reach the need and FaceLook's span
 * (WallStopReach), a wall first seen far ahead held to a floor from all of the throttle to half
 * over 0.15 s with that time's speed added to its need (WallStopPersist, WallStopNear), the longer
 * rays along the turn's arc (WallStopArc), the need never under a wheel radius and 10 (WallStop
 * Short; test 46's guard rail crept into at 202). Each with its off value: test 46's build. */
static void WallStopTests47(void)
{
	static const char wallAt[] = "rays: a wall ahead (90 deg): ", easeAt[] = "(FakeWall, layer 1), the throttle eased to ", stopWord[] = ": WallStop)";
	float R = 29.9f, edge = 99.6f + 29.9f;

	printf("WallStop (test 46's glimpses): a raised rail dead ahead placed 1100 ahead at 900, W held: first seen about 810 past the front wheel by the longer rays "
	       "(the need 400 and 0.15 s of the speed, and FaceLook's 275: WallStopReach, WallStopPersist), the throttle over 80%% then, eased down from there, stopped a wheel radius and 10 short (WallStopShort):\n");
	UpToSpeed(0.0f);
	int wall0 = LogLines(wallAt), looked0 = LogLines("), seen by the longer rays, ");
	RaisedRail(1100.0f, 0.0f);
	GlimpseWatch(g_stopW, 0.0f, 0.3f);
	RunFrames(3500);
	float moved = AlongStill(), first = NthLogNumber(wallAt, wall0), firstEase = NthLogNumber(easeAt, wall0), looked = NthLogNumber("), seen by the longer rays, ", looked0);
	CHECK(first > 700.0f && first <= 815.0f && first <= looked + 2.0f && firstEase >= 80.0f && NthLogLineHas(wallAt, wall0, ", and 0.15 s of the speed for a wall first seen past FaceLook's reach (WallStopPersist), seen by the longer rays, ") &&
	          looked > 740.0f && looked < 830.0f && g_glimpseLeast >= 0.5f && g_stopLeast >= R + 5.0f && g_stopLeast <= R + 30.0f && moved < 5.0f,
	      "first seen %.0f past the front wheel, eased to %.0f%% (\"...needs 535 past the front wheel: 400, and 0.15 s of the speed for a wall first seen past FaceLook's reach (WallStopPersist), seen by the longer rays, %.0f past it (WallStopReach)...\"), "
	      "the input over half its first 0.3 s (least %.2f), the front wheel's edge %.0f from it at the closest (a wheel radius and 10: %.0f), stopped (%.1f in 0.25 s)", first, firstEase, looked, g_glimpseLeast, g_stopLeast, R + 10.0f, moved);
	DoneRiding();

	/* The rail of test 45 placed 187 past the front wheel (where test 45's rays first saw it):
	 * within FaceLook's reach, at a speed whose stop needs more, 165 or more ahead (0.15 s of 900
	 * and a wheel radius): WallStopNear=1, its floor, then none; WallStopNear=0 (the default since
	 * the review of test 47's build: the floor's time has such a wall hit harder): none at once. */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (!off)
			RewriteIni("WallStopNear=0", "WallStopNear=1");
		printf("WallStop (test 46's 15:47.9): %sthe rail placed 187 past the front wheel at 900, W held: %s:\n", off ? "WallStopNear=0, the default: " : "WallStopNear=1 written: ",
		       off ? "the throttle none at once, as in test 46's build" : "held to a floor from 100% (\"(WallStopNear)\"), under half only after 0.15 s, then none");
		UpToSpeed(0.0f);
		wall0 = LogLines(wallAt);
		RaisedRail(edge + 187.0f, 0.0f);
		GlimpseWatch(g_stopW, 0.0f, 0.14f);
		RunFrames(140);
		float early = g_glimpseLeast;
		GlimpseWatch(g_stopW, 0.0f, 0.2f);
		RunFrames(260);
		first = NthLogNumber(wallAt, wall0);
		firstEase = NthLogNumber(easeAt, wall0);
		if (off)
			CHECK(first > 160.0f && first <= 187.0f && firstEase == 0.0f && NthLogLineHas(wallAt, wall0, "the throttle eased to 0% (a stop from ") && NthLogLineHas(wallAt, wall0, " past the front wheel: WallStop)") && early < 0.2f,
			      "first seen %.0f past the front wheel, eased to %.0f%% at once (\"(a stop from 900 needs 400 past the front wheel: WallStop)\"), the input %.2f at the least in its first 0.14 s", first, firstEase, early);
		else
			CHECK(first > 160.0f && first <= 187.0f && firstEase >= 90.0f && NthLogLineHas(wallAt, wall0, " s (WallStopNear): WallStop)") && early >= 0.5f && g_glimpseLeast < 0.2f,
			      "first seen %.0f past the front wheel, held to %.0f%% (\"; held to ... till it has stayed 0.15 s, seen 0.00 s (WallStopNear): WallStop)\"), the input %.2f at the least in its first 0.14 s, %.2f after",
			      first, firstEase, early, g_glimpseLeast);
		DoneRiding();
		if (!off)
			RewriteIni("WallStopNear=1", "WallStopNear=0");
	}

	/* Test 46's 15:47.9: a post 200 past the front wheel whose normal reads 15 deg off the heading
	 * (alongside by its normal, the rays either side missing it: FaceLook's ease, as the lawn
	 * flamingo), the rail 70 behind it; the post gone after 0.1 s (ridden past): the verdict, a
	 * wall still, moves to the rail and WallStop, and a line says so. */
	printf("WallStop (test 46's 15:47.9): a post 200 past the front wheel at 900 whose normal reads 15 deg off the heading, a raised rail 70 behind it, the post gone after 0.1 s, W held: "
	       "the verdict moving to the rail and WallStop logged (\"(the verdict moved: the last line had FakeWall at 73..85%%)\"):\n");
	{
		UpToSpeed(0.0f);
		int moved0 = LogLines("(the verdict moved: the last line had FakeWall at "), post0 = LogLines("(alongside by its normal, 15 deg off the heading, but the rays either side don't say so: ");
		FakePlane *post = AlongPlane(0, edge + 200.0f, 15.0f, 10.0f, CAP_NONE);
		g_alongW = NULL;
		FakePlane *rail = Obstacle(1, edge + 270.0f, 60.0f, CAP_NONE, 10.0f, 1, NULL);
		rail->bottom = 20.0f;
		GlimpseWatch(post, 0.1f, 0.0f);
		RunFrames(400);
		int movedLines = LogLines("(the verdict moved: the last line had FakeWall at ") - moved0, posts = LogLines("(alongside by its normal, 15 deg off the heading, but the rays either side don't say so: ") - post0;
		float was = NthLogNumber("(the verdict moved: the last line had FakeWall at ", moved0);
		CHECK(posts >= 1 && movedLines == 1 && was >= 60.0f && was <= 95.0f && NthLogLineHas("(the verdict moved: the last line had FakeWall at ", moved0, ": WallStop) (the verdict moved"),
		      "the post's line (%d), then one \"... : WallStop) (the verdict moved: the last line had FakeWall at %.0f%%)\" line (%d)", posts, was, movedLines);
		DoneRiding();
	}

	/* A glimpse: the rail 600 past the front wheel for 0.1 s at 900 (past the need and its extra,
	 * 535: the floor has the slack): the floor leaves two thirds; WallStopPersist=0, the rail 400
	 * past it (where the Sanctuary minute's were seen, test 46's reach): the throttle none, as in
	 * test 46's build. */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("WallStopPersist=0.15", "WallStopPersist=0");
		printf("WallStop (test 46's glimpses): %sa raised rail %s past the front wheel at 900 for 0.1 s, W held: %s:\n", off ? "WallStopPersist=0 written: " : "", off ? "400" : "600",
		       off ? "the throttle none, as in test 46's build" : "the input never under about 70% (the floor at 0.1 s: two thirds), a \"held to\" line");
		UpToSpeed(0.0f);
		wall0 = LogLines(wallAt);
		int held0 = LogLines("till it has stayed 0.15 s, seen ");
		RaisedRail(edge + (off ? 400.0f : 600.0f), 0.0f);
		GlimpseWatch(g_stopW, 0.1f, 0.15f);
		RunFrames(600);
		int walls = LogLines(wallAt) - wall0, held = LogLines("till it has stayed 0.15 s, seen ") - held0;
		if (off)
			CHECK(walls >= 1 && g_glimpseLeast < 0.2f && held == 0, "%d wall line(s), the input %.2f at the least (none), no \"held to\" line (%d)", walls, g_glimpseLeast, held);
		else
			CHECK(walls >= 1 && g_glimpseLeast >= 0.62f && held >= 1, "%d wall line(s), \"held to ... till it has stayed 0.15 s\" (%d), the input %.2f at the least (over 0.62)", walls, held, g_glimpseLeast);
		if (!off) {
			/* Review of test 47's build: a wall first seen by the longer rays between the need and
			 * its extra (a rail that turns into their line 420 past the front wheel at 900: the need
			 * 400, with the extra 535) has no room for the floor's 0.15 s: the floor holds only while
			 * it is past the need, so the throttle is none within a frame or two, and the bike stops
			 * short of it (test 46's build, its rays reaching the need, cut at 400). Placed 20 past
			 * the need at the speed the bike is back to (the climb's [Steer]: 0.6 of 900 / 0.4). */
			RunFrames(400);
			float v = g_fakeSpeedNow, needAt = v * v / 2700.0f + 0.1f * v + 10.0f;
			printf("WallStop (review of test 47's build): back to %.0f, a raised rail placed 20 past the need, %.0f past the front wheel (short of its extra, %.0f), W held: the floor only till it is at the need: the input under 0.2 within 0.1 s, stopped short of it:\n",
			       v, needAt + 20.0f, needAt + 0.15f * v);
			RaisedRail(edge + needAt + 20.0f, 0.0f);
			GlimpseWatch(g_stopW, 0.0f, 0.1f);
			RunFrames(3000);   /* the last of the stop creeps to WallStopShort's 40, as the first ride's */
			float still = AlongStill();
			CHECK(v > 800.0f && g_glimpseLeast < 0.2f && g_stopLeast > 0.0f && still < 5.0f, "the input %.2f at the least in its first 0.1 s, the front wheel's edge %.1f from it at the closest, stopped (%.1f in 0.25 s)", g_glimpseLeast, g_stopLeast, still);
		}
		DoneRiding();
		if (off)
			RewriteIni("WallStopPersist=0", "WallStopPersist=0.15");
	}

	/* Turning past: the camera (and the bike) turning right at 40 deg/s at 900, a wall 160 wide
	 * placed square across the heading 600 ahead: the bike's arc passes 70 right of its end, the
	 * straight rays sweep across it for about 0.23 s. Along the arc: never seen, the throttle
	 * full; WallStopArc=0: seen straight ahead, over 0.15 s, cut. */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("WallStopArc=90", "WallStopArc=0");
		printf("WallStop (test 46's glimpses): %sturning right at 40 deg/s at 900, a raised rail 160 wide across the heading 600 ahead, W held: %s:\n", off ? "WallStopArc=0 written: " : "",
		       off ? "seen by the straight rays for about 0.23 s, the throttle cut, as in test 46's build" : "the longer rays along the arc, which passes 70 right of its end: no wall line, the input full");
		UpToSpeed(0.0f);
		g_glimpseTurn = 40.0f / DEG;
		RunFrames(600);
		wall0 = LogLines(wallAt);
		int stop0 = LogLines(stopWord);
		FakePlane *w = RaisedRail(600.0f, 80.0f);
		GlimpseWatch(w, 0.0f, 1.0f);
		RunFrames(1100);
		int walls = LogLines(wallAt) - wall0, stops = LogLines(stopWord) - stop0;
		float gap = FaceGap(w);
		if (off)
			CHECK(stops >= 1 && g_glimpseLeast < 0.5f, "%d WallStop line(s) (%d wall), the input %.2f at the least", stops, walls, g_glimpseLeast);
		else
			CHECK(walls == 0 && stops == 0 && g_glimpseLeast >= 0.95f && gap < 0.0f, "no wall line (%d, %d WallStop), the input %.2f at the least, past it (%.0f)", walls, stops, g_glimpseLeast, gap);
		if (!off) {
			/* Review of test 47's build: the arc's chords leave the heading's line at once, so they
			 * meet things within FaceLook's reach the straight rays pass. A post 20 across on the
			 * longer rays' first chord 150 past the front wheel (inside FaceLook's 275), gone after
			 * 0.1 s (turned past): not counted, no WallStop line, the input as it was; test 47's
			 * build cut it to nothing at once. The chord's heading as FaceRays has it: half the
			 * arc's turn to its half-way point, the longer rays' reach the need, its extra and the
			 * span (the climb's [Steer]). */
			float v = g_fakeSpeedNow, needAt = v * v / 2700.0f + 0.1f * v + 10.0f, reach = needAt + 0.15f * v + 0.3f * v + 5.0f;
			float chord = 0.5f * (40.0f / DEG) / v * 0.5f * (edge + reach), c = edge + 150.0f, h = PlayerHeading();
			FakePlane *post = Obstacle(1, c * cosf(chord), 60.0f, CAP_NONE, 10.0f, 1, NULL);
			post->point[0] += cosf(h) * c * sinf(chord);
			post->point[1] -= sinf(h) * c * sinf(chord);
			post->halfWidth = 10.0f;
			printf("WallStop (review of test 47's build): still turning at %.0f, a post 20 across on the longer rays' first chord 150 past the front wheel (%.0f right of the heading, inside FaceLook's reach), gone after 0.1 s: not counted, no WallStop line, the input as it was:\n",
			       v, c * sinf(chord));
			stop0 = LogLines(stopWord);
			GlimpseWatch(post, 0.1f, 0.1f);
			RunFrames(300);
			stops = LogLines(stopWord) - stop0;
			CHECK(stops == 0 && g_glimpseLeast >= 0.9f, "%d WallStop line(s) (0), the input %.2f at the least in its first 0.1 s", stops, g_glimpseLeast);
		}
		DoneRiding();
		if (off)
			RewriteIni("WallStopArc=0", "WallStopArc=90");
	}

	/* Test 46's guard rail at 202 (16:43): the bike no faster than 200, the rail 400 ahead: stopped
	 * with the front wheel's edge a wheel radius and 10 short; WallStopShort=0: about 10, as in
	 * test 46's build. */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("WallStopShort=10", "WallStopShort=0");
		printf("WallStop (test 46's 16:43): %sa raised rail 400 ahead at 200 (the fake no faster), W held: %s:\n", off ? "WallStopShort=0 written: " : "",
		       off ? "the front wheel's edge stopped about 10 from it, as in test 46's build" : "the front wheel's edge stopped a wheel radius and 10 from it (WallStopShort)");
		UpToSpeed(200.0f);
		RaisedRail(400.0f, 0.0f);
		RunFrames(3000);
		float still = AlongStill();
		if (off)
			CHECK(g_stopLeast >= 0.0f && g_stopLeast < 25.0f && still < 5.0f, "the front wheel's edge %.1f from it at the closest, stopped (%.1f in 0.25 s)", g_stopLeast, still);
		else
			CHECK(g_stopLeast >= R + 5.0f && g_stopLeast <= R + 20.0f && still < 5.0f, "the front wheel's edge %.1f from it at the closest (a wheel radius and 10: %.1f), stopped (%.1f in 0.25 s)", g_stopLeast, R + 10.0f, still);
		DoneRiding();
		if (off)
			RewriteIni("WallStopShort=0", "WallStopShort=10");
	}
	g_onFrame = ClimbFrame;
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
}

/* Test 46's rails (the note's 3). NarrowBoth: at 2:24.3 a wooden road barrier met at a shallow
 * angle read "narrow, the ray 36 to the left passes it at 18 and 24": the side ray along the
 * heading on one side passes it (here the left one, cast from 36 back, starts past its line). A
 * barrier 27 high and 10 deep whose line lies 18 deg off the heading, crossing it 400 ahead, the
 * capsule held at it (no slide: stalled, so the lines 12 to either side judge it and say why): not
 * narrow (the side rays across its face meet it on both sides), no boost; with NarrowBoth=0
 * narrow by the left side ray, the boost on, as in test 46's build. A fallen board 22 high, 40 across and 10 deep met 10 from its left end: narrow still (the
 * side rays pass both its ends), climbed. UnderBikeTop: at 2:20.45 a barrier's face 16 behind the
 * front wheel's edge with that wheel 49 up on it was held to 55% "under the bike", and the bike
 * rode on top of it. A face 100 ahead of the rider wherever they go (behind the wheel's edge) and
 * a disc 49 over the ground under the front wheel alone: a wall, no forward input; with
 * UnderBikeTop=0 under the bike, held to the obstacle's 55% (rolling on, 0.15 to 0.75 of a
 * full-throttle start's run: the pitched rays read the disc's top between), as in
 * test 46's build. A real thing under the bike as before: the ground 40 up under both wheels, the front wheel 49 up with the feet 20
 * over the ground behind, and the front wheel 25 up (under ClimbTop). Each on a ride of its own;
 * ClimbMaxTop=18 for the first, put back to the 0 the run starts with after. Run after the
 * WallStop rides: the "held to 55%" walls here are "rays: a wall ahead (90 deg): " lines without
 * "the throttle eased to", which those index by (NthLogNumber with one count for both). */
static void RailTests47(void)
{
	float cos85 = cosf(85.0f / DEG), p0[2];
	static const char boostWords[] = "the climb limit 47 -> 85";
	static const char acrossWords[] = "; the side rays cast across its face, its line 18 deg off the heading (NarrowBoth)";
	static const char eitherWords[] = "and long (the rays 36 to either side meet it too, cast at 18";
	static const char sideWords[] = "ahead: narrow, the ray 36 to the left passes it";   /* at 18, or at 18, 20 and 24 (NarrowHeights), by the frame it is judged at */
	RewriteIni("ClimbMaxTop=0", "ClimbMaxTop=18");
	g_capSlip = 0.0f;   /* held at the barrier, stalled: the lines 12 to either side judge it (the one along the heading meets it 58 ahead, past the capsule's reach) */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("NarrowHeights=3\n", "NarrowHeights=3\nNarrowBoth=0\n");
		printf("rails (test 46, 2:24.3): %sa wooden road barrier 27 high and 10 deep, its line 18 deg off the heading crossing it 400 ahead, W held 4 s: %s:\n", off ? "NarrowBoth=0 written: " : "",
		       off ? "narrow by the side ray to the left (cast along the heading from 36 back, it starts past the barrier's line), the boost on, as in test 46's build"
		           : "not narrow (the side rays across its face meet it on both sides), no boost, the limit 47 throughout, the beam line saying so");
		GetOffAndOn(45.0f);
		g_camYaw = PlayerHeading();
		int boost0 = LogLines(boostWords), narrow0 = LogLines("ahead: narrow, "), across0 = LogLines(acrossWords), either0 = LogLines(eitherWords), side0 = LogLines(sideWords);
		g_slopeMin = 1.0f;
		FakePlane *w = Obstacle(0, 400.0f, 27.0f, CAP_STEP, 10.0f, 1, NULL);
		g_planeTopDepth[0] = 10.0f;
		TurnPlane(w, 72.0f);   /* its line 18 deg off the heading, its far end to the right */
		if (off) {
			float took = UntilBoost(cos85, 4000);
			CHECK(took > 0.0f && LogLines(sideWords) - side0 == 1, "the boost on at the barrier (%.2f s), the line saying \"...; at 18 ... %s...\" (%d; the ray 36 to the left and 36 back starts past its line)", took, sideWords,
			      LogLines(sideWords) - side0);
		} else {
			Keys(0.0f, 1.0f);
			RunFrames(4000);
			CHECK(Near(g_slopeMin, COS47) && LogLines(boostWords) == boost0 && LogLines("ahead: narrow, ") == narrow0,
			      "no boost (the steepest limit %.2f deg, %d boost line(s)), no narrow word (%d)", acosf(g_slopeMin) * DEG, LogLines(boostWords) - boost0, LogLines("ahead: narrow, ") - narrow0);
			CHECK(LogLines(acrossWords) - across0 >= 1 && LogLines(eitherWords) - either0 >= 1,
			      "held at it, stalled: \"climb: stopped with forward held (...): not climbed: a beam with a drop behind it ... %s...%s\" (%d, %d)", eitherWords, acrossWords,
			      LogLines(eitherWords) - either0, LogLines(acrossWords) - across0);
		}
		RollOff();
		if (off)
			RewriteIni("NarrowHeights=3\nNarrowBoth=0\n", "NarrowHeights=3\n");
	}
	g_capSlip = 1.0f;

	printf("rails (test 46): NarrowBoth=1 again, a fallen board 22 high, 40 across and 10 deep 400 ahead, met 10 from its left end (both ends within the side rays' 36), SetPosition honoured, W held: narrow still, the boost on, over it:\n");
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	{
		static const char bothWords[] = "ahead: narrow, the rays 36 to either side across its face pass it";
		int boost0 = LogLines(boostWords), both0 = LogLines(bothWords), beam0 = LogLines("not climbed: a beam");
		float h = PlayerHeading();
		FakePlane *w = Obstacle(0, 400.0f, 22.0f, CAP_STEP, 10.0f, 1, NULL);
		w->point[0] += cosf(h) * 10.0f;   /* its middle 10 to the right of the line */
		w->point[1] -= sinf(h) * 10.0f;
		w->halfWidth = 20.0f;
		g_planeTopDepth[0] = 10.0f;
		float passed = RideAt(w, 10.0f, 4000);
		CHECK(passed > 0.0f && LogLines(boostWords) - boost0 >= 1 && LogLines(bothWords) - both0 >= 1 && LogLines("not climbed: a beam") == beam0,
		      "over it within 4 s (%.2f s), the boost on (%d), the low face line saying \"...; at 18 ... %s\" (%d), no beam line", passed, LogLines(boostWords) - boost0, bothWords,
		      LogLines(bothWords) - both0);
		RollOff();
	}
	RewriteIni("ClimbMaxTop=18", "ClimbMaxTop=0");

	/* UnderBikeTop: the capsule's model off, so the ground can be moved under the wheels with the
	 * feet where they are (test 35's checks in the full run do the same). */
	g_capsuleOn = false;
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	Mark(p0);
	Keys(0.0f, 1.0f);
	RunFrames(2000);
	float fullRun = Moved(p0), ground0 = g_groundZ;
	Keys(0.0f, 0.0f);
	RunFrames(2500);
	static const char inWords[] = "a face the front wheel is in, a wall; UnderBikeTop)";
	static const char atWords[] = "(behind the wheel's edge, the front wheel 49 up on it, over ClimbTop's 31.9, the rear wheel's ground 0 ";
	static const char underWords[] = "(under the bike, the front wheel ";
	for (int k = 0; k < 5; k++) {
		bool off = k == 1;
		float front = k == 2 ? 40.0f : k == 4 ? 25.0f : 49.0f, feet = k == 3 ? 20.0f : 0.0f;
		const char *what = k == 0 ? "a face 100 ahead of the rider (behind the front wheel's edge), a disc 49 over the ground under the front wheel alone: a wall, no forward input"
		                   : k == 1 ? "UnderBikeTop=0 written, the same: under the bike, rolling at the obstacle's 55%, as in test 46's build"
		                   : k == 2 ? "UnderBikeTop=1 again, the same face, the ground 40 up under both wheels (test 35's stone): under the bike as before, 55%"
		                   : k == 3 ? "the same face, the front wheel 49 up, the feet 20 over the ground behind (up on the thing): under the bike as before, 55%"
		                            : "the same face, a disc 25 over the ground under the front wheel (under ClimbTop): under the bike as before, 55%";
		printf("rails (test 46, 2:20.45): %s:\n", what);
		if (off)
			RewriteIni("NarrowHeights=3\n", "NarrowHeights=3\nUnderBikeTop=0\n");
		else if (k == 2)
			RewriteIni("NarrowHeights=3\nUnderBikeTop=0\n", "NarrowHeights=3\n");
		if (off || k == 2) {
			GetOffAndOn(45.0f);
			g_camYaw = PlayerHeading();
		}
		int in0 = LogLines(inWords), at0 = LogLines(atWords), under0 = LogLines(underWords);
		FakePlane *face = Obstacle(0, 100.0f, 0.0f, CAP_NONE, 10.0f, 1, NULL);
		face->follow = 100.0f;   /* 100 ahead of the rider wherever they go: 29.5 behind the front wheel's edge */
		g_groundZ = ground0 + (k == 2 ? 40.0f : -feet);
		if (k != 2) {
			g_shelfOn = true;
			g_shelfHeight = front + feet;
			g_shelfAhead = 99.6f;   /* over the front axle */
			g_shelfRadius = 25.0f;   /* clear of the rear wheel's ray and the face rays */
		}
		Mark(p0);
		Keys(0.0f, 1.0f);
		RunFrames(2000);
		float moved = Moved(p0), input = MoveInput()[1];
		if (k == 0)
			CHECK(moved < 30.0f && input == 0.0f && LogLines(inWords) - in0 >= 1 && LogLines(atWords) - at0 >= 1 && LogLines(underWords) == under0,
			      "stands: %.0f in 2 s, no forward input (%.3f), \"rays: a wall ahead (...): ... the throttle eased to 0%% %s...: %s\" (%d, %d), no \"under the bike\" line",
			      moved, input, atWords, inWords, LogLines(atWords) - at0, LogLines(inWords) - in0);
		else
			CHECK(moved > 0.15f * fullRun && moved < 0.75f * fullRun && LogLines(underWords) - under0 >= 1 && LogLines(inWords) == in0,
			      "rolls on held: %.0f in 2 s (%.0f at full throttle; the obstacle's 55%% with the face rays' pitched hits between), \"%s%.0f up on it: an obstacle, not a wall)\" (%d), no \"%s\"", moved, fullRun,
			      underWords, front, LogLines(underWords) - under0, inWords);
		Keys(0.0f, 0.0f);
		face->on = false;
		face->follow = 0.0f;
		g_shelfOn = false;
		g_shelfHeight = g_shelfAhead = 0.0f;
		g_shelfRadius = 60.0f;
		g_groundZ = ground0;
		RunFrames(2500);
	}
	g_capsuleOn = true;
	ClearObstacles();
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
}

/* --- Mode 19 'wall' (2026-11-01a: test 47's WallStop cuts at full speed in Sanctuary and the wooden road barriers climbed at
 * 10-30 deg): FaceArc (FaceLook's rays along the turn's arc too, a wall only one path meets eased by FaceLook's own ease),
 * WallStopClimb (the longer rays as without the climb's boost while it is on, a wall they see past FaceLook's reach not
 * counting for the climb) and ClimbLegs (a face round at its foot a log only if solid at 4 where the side rays across it meet
 * it higher). Mode 10's world and [Steer], with the three written at their defaults so rides can rewrite each to its 0, the
 * 2026-10-31a build. Speeds 900, the fake's front wheel's edge 129.5 ahead of the axis, FaceLook's span 275, the need 400. */

/* The number right after `after` on the (skip + 1)-th line holding `text` (NAN: no such line, or no number there). */
static float NthLineNumber(const char *text, int skip, const char *after)
{
	static char line[4096];
	FILE *f = OpenLog();
	if (!f)
		return NAN;
	float value = NAN;
	while (fgets(line, sizeof(line), f)) {
		if (!strstr(line, text) || skip-- > 0)
			continue;
		const char *at = strstr(line, after);
		if (at) {
			char *end;
			float v = strtof(at + strlen(after), &end);
			if (end != at + strlen(after))
				value = v;
		}
		break;
	}
	fclose(f);
	return value;
}

/* Whether the first trace line after the (skip + 1)-th line holding `text` holds `also` (the trace's climb word at that time). */
static bool TraceAfterHas(const char *text, int skip, const char *also)
{
	static char line[4096];
	FILE *f = OpenLog();
	if (!f)
		return false;
	bool found = false, has = false;
	while (fgets(line, sizeof(line), f)) {
		if (!found) {
			found = strstr(line, text) && skip-- <= 0;
			continue;
		}
		if (strstr(line, " trace: ")) {
			has = strstr(line, also) != NULL;
			break;
		}
	}
	fclose(f);
	return has;
}

/* The climb's limit at its loosest (cos: the largest) over a watch from when a wall was placed, beside the glimpse's watch:
 * the boost held the whole time if it stays cos 85; and the front wheel's edge (129.5 along the heading, wherever it points) to
 * the stop's wall along its normal at the least (StopFrame's measure assumes the bike square to it, which a turn undoes). */
static float g_wallSlopeMax, g_wallSlopeWatch, g_wallGapLeast;
static void WallFrame(float dt)
{
	GlimpseFrame(dt);
	if (g_glimpseW && g_glimpseT <= g_wallSlopeWatch && *Slope() > g_wallSlopeMax)
		g_wallSlopeMax = *Slope();
	if (g_stopW && g_stopW->on) {
		float h = PlayerHeading(), e[2] = { PlayerPos()[0] + sinf(h) * 129.5f, PlayerPos()[1] + cosf(h) * 129.5f };
		float gap = (e[0] - g_stopW->point[0]) * g_stopW->normal[0] + (e[1] - g_stopW->point[1]) * g_stopW->normal[1];
		if (gap < g_wallGapLeast)
			g_wallGapLeast = gap;
	}
}

/* Where FaceLook's axle ray along the turn's arc is `along` from the axis (CastArcEx's chords: FaceLook's reach at v, cut where the
 * arc has turned FaceArc's 90, in 2 to 4 pieces), ahead of and to the right of the axis along the heading now. */
static void FaceArcPoint(float v, float rate, float along, float *ahead, float *right)
{
	float k = rate / v, len = 129.5f + 0.3f * v + 5.0f, most = (90.0f / DEG) / fabsf(k);
	len = len < most ? len : most;
	int pieces = (int)ceilf(fabsf(k) * len / 0.3f);
	pieces = pieces < 2 ? 2 : pieces > 4 ? 4 : pieces;
	float ds = len / (float)pieces, x = 0.0f, y = 0.0f, done = 0.0f;
	for (int i = 0; i < pieces; i++) {
		float ah = k * (ds * (float)i + 0.5f * ds), c = 2.0f * sinf(0.5f * k * ds) / k, step = done + c >= along ? along - done : c;
		x += cosf(ah) * step;
		y += sinf(ah) * step;
		done += step;
		if (done >= along)
			break;
	}
	*ahead = x;
	*right = y;
}

/* FaceArc (2026-11-01a, test 47's 28 cuts by FaceLook's straight rays): turning right at 100 deg/s at 900, a post on the heading's
 * line 200 past the front wheel (beside the turn: FaceLook's arc passes it 102 to the right), a post on FaceLook's arc 200 past it
 * (on the turn: the straight rays pass it 102 to the left), and turning at 40 deg/s a rail across the heading 250 past it (both
 * paths meet it). Each with FaceArc=0 too (the 2026-10-31a build) but the last, which keeps WallStop's cut. */
static void WallFaceArcTests(void)
{
	static const char wallAt[] = "rays: a wall ahead (", stopWord[] = ": WallStop)";
	static const char besideWord[] = "the straight rays only, beside the turn's arc: FaceLook's ease (FaceArc)", arcWord[] = "along the turn's arc only: FaceLook's ease (FaceArc)";
	static const char bothWord[] = "along the turn's arc (FaceArc), the straight rays meeting it too";
	float edge = 99.6f + 29.9f;
	RewriteIni("WallStopNarrow=40", "WallStopNarrow=0");   /* 2026-11-02a: the posts here are 20 and 30 across, 2026-11-01a's scenarios (WallNarrowTests has the narrow ones) */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("FaceArc=90", "FaceArc=0");
		printf("FaceArc (test 47's street lamp at 19:43:15): %sturning right at 100 deg/s at 900, a post 20 across on the heading's line 200 past the front wheel (FaceLook's arc passes it 102 to the right), W held: %s:\n",
		       off ? "FaceArc=0 written: " : "", off ? "WallStop's cut to 0%, as in the 2026-10-31a build" : "no WallStop line, one \"the straight rays only, beside the turn's arc: FaceLook's ease (FaceArc)\" line at 70-73%, the input 0.68 or more");
		UpToSpeed(0.0f);
		g_glimpseTurn = 100.0f / DEG;
		RunFrames(500);
		int stop0 = LogLines(stopWord), beside0 = LogLines(besideWord), wall0 = LogLines(wallAt), offText = LogLines("FaceLook's rays straight along the heading: the straight rays alone (FaceArc=0); ");
		float v = g_fakeSpeedNow, want = 100.0f * 200.0f / (0.3f * v + 5.0f);   /* FaceLook's ease: 200 over its span (73% at 900) */
		FakePlane *post = RaisedRail(edge + 200.0f, 10.0f);
		GlimpseWatch(post, 0.0f, 0.1f);
		RunFrames(300);
		int stops = LogLines(stopWord) - stop0, beside = LogLines(besideWord) - beside0, walls = LogLines(wallAt) - wall0;
		float eased = NthLineNumber(besideWord, beside0, "the throttle eased to "), rate = NthLineNumber(besideWord, beside0, "the heading's rate ");
		if (off)
			CHECK(offText == 1 && stops == 1 && NthLogLineHas(stopWord, stop0, "the throttle eased to 0% (") && g_glimpseLeast < 0.2f && beside == 0,
			      "the settings line \"... the straight rays alone (FaceArc=0)\" (%d), %d WallStop line (1) at 0%%, the input %.2f at the least in 0.1 s (under 0.2)", offText, stops, g_glimpseLeast);
		else {
			CHECK(stops == 0 && walls == 1 && beside == 1 && eased >= 70.0f && eased <= 82.0f,
			      "no WallStop line (%d), one wall line (%d) saying \"...; %s, ...\" (%d) at %.0f%% (FaceLook's ease, 200 over its span: %.0f at the fake's %.0f, up to 82 at the plugin's own reading of 800 or more)",
			      stops, walls, besideWord, beside, eased, want, v);
			CHECK(rate >= 80.0f && rate <= 110.0f, "the line gives the heading's rate: \"the heading's rate %+.0f deg/s\" (80-110: the camera's 100, smoothed over 0.1 s)", rate);
			CHECK(g_glimpseLeast >= 0.68f, "the input %.2f at the least in its first 0.1 s (0.68 or more; 2026-10-31a: under 0.2)", g_glimpseLeast);
		}
		DoneRiding();
		if (off)
			RewriteIni("FaceArc=0", "FaceArc=90");
	}

	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("FaceArc=90", "FaceArc=0");
		printf("FaceArc: %sturning right at 100 deg/s at 900, a post 30 across on FaceLook's arc 200 past the front wheel (the straight rays pass it on the left), W held: %s:\n", off ? "FaceArc=0 written: " : "",
		       off ? "no wall line, the input full, as in the 2026-10-31a build" : "\"along the turn's arc only: FaceLook's ease (FaceArc)\" 190-205 past the front wheel, the input under 0.76 within 0.05 s, no WallStop line");
		UpToSpeed(0.0f);
		g_glimpseTurn = 100.0f / DEG;
		RunFrames(500);
		float v = g_fakeSpeedNow, ahead, right, h = PlayerHeading();
		FaceArcPoint(v, 100.0f / DEG, edge + 200.0f, &ahead, &right);
		int stop0 = LogLines(stopWord), arc0 = LogLines(arcWord), wall0 = LogLines(wallAt);
		FakePlane *post = RaisedRail(ahead, 15.0f);
		post->point[0] += cosf(h) * right;
		post->point[1] -= sinf(h) * right;
		GlimpseWatch(post, 0.0f, off ? 0.1f : 0.05f);
		RunFrames(off ? 110 : 60);
		float early = g_glimpseLeast;
		int stops = LogLines(stopWord) - stop0, arcs = LogLines(arcWord) - arc0, walls = LogLines(wallAt) - wall0;   /* in the watch: on the arc the bike reaches it in 0.25 s */
		float nearer = 9.0f;
		for (int t = 0; t < 8 && !off; t++) {   /* 0.06 to 0.14 s in: the ease falling as it nears (about 120 past the front wheel by then) */
			RunFrames(10);
			float in = hypotf(MoveInput()[0], MoveInput()[1]);
			nearer = in < nearer ? in : nearer;
		}
		float first = NthLineNumber(arcWord, arc0, " deg): ");
		if (off)
			CHECK(walls == 0 && early >= 0.95f, "no wall line (%d), the input %.2f at the least in its first 0.1 s (0.95 or more)", walls, early);
		else
			CHECK(stops == 0 && arcs >= 1 && first >= 190.0f && first <= 205.0f && early < 0.76f,
			      "at %.0f, the post %.0f ahead and %.0f right: \"rays: a wall ahead (.. deg): %.0f past the front wheel ... %s ...\" (%d; 190-205), no WallStop line (%d), the input %.2f at the least in its first 0.05 s (under 0.76)",
			      v, ahead, right, first, arcWord, arcs, stops, early);
		if (!off)
			CHECK(nearer < early - 0.1f, "the input falling as it nears: %.2f at the least 0.06 to 0.14 s in, from %.2f in its first 0.05 s (2026-10-31a: full throughout)", nearer, early);
		DoneRiding();
		if (off)
			RewriteIni("FaceArc=0", "FaceArc=90");
	}

	/* 3b's climb (test 47's 20:03:06.429, a boost over a kerb cut by the mailbox beside the turn): the boost on at a low log while
	 * turning, then the post on the heading's line 200 past the front wheel: only the straight rays meet it, so it isn't a wall
	 * for the climb (FaceArc=0: CLIMB_WALL, the boost cut). */
	static const char cutWords[] = "climb: cut after ", wallCut[] = ": a wall ahead (the face rays' verdict)";
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("FaceArc=90", "FaceArc=0");
		printf("FaceArc (test 47's 20:03:06): %sturning right at 100 deg/s at 900, the climb's boost on at a low log 8 across, then a post on the heading's line 200 past the front wheel (beside the turn), W held: %s:\n",
		       off ? "FaceArc=0 written: " : "", off ? "the boost cut, \"a wall ahead (the face rays' verdict)\", as in the 2026-10-31a build" : "the boost not cut by it");
		RewriteIni("Climb=1\n", "Climb=1\nClimbHold=1.0\n");
		UpToSpeed(0.0f);
		g_glimpseTurn = 100.0f / DEG;
		RunFrames(500);
		FakePlane *log = Obstacle(1, 150.0f, 8.0f, CAP_LOG, 8.0f, 1, NULL);
		log->round = true;
		float took = UntilBoost(cosf(85.0f / DEG), 1000);
		int cut0 = LogLines(cutWords), wallCut0 = LogLines(wallCut);
		FakePlane *post = RaisedRail(edge + 200.0f, 10.0f);
		GlimpseWatch(post, 0.0f, 0.1f);
		RunFrames(300);
		int cuts = LogLines(wallCut) - wallCut0, anyCut = LogLines(cutWords) - cut0;
		if (off)
			CHECK(took > 0.0f && cuts == 1, "the boost on at the log (%.2f s), then \"climb: cut after ...%s\" (%d)", took, wallCut, cuts);
		else
			CHECK(took > 0.0f && cuts == 0 && anyCut == 0, "the boost on at the log (%.2f s), no \"climb: cut after ...\" line in the 0.3 s after the post (%d, %d for the wall)", took, anyCut, cuts);
		DoneRiding();
		RewriteIni("Climb=1\nClimbHold=1.0\n", "Climb=1\n");
		if (off)
			RewriteIni("FaceArc=0", "FaceArc=90");
	}

	for (int k = 0; k < 2; k++) {
		bool slow = k == 1;
		float ahead = slow ? 100.0f : 250.0f;   /* slow: inside FaceLook's reach (its span 120 at 380-400; at 120 the longer rays met it first) */
		printf("FaceArc: turning right at 40 deg/s at %s, a raised rail across the heading %.0f past the front wheel (FaceLook's arc %s off the line there, still on it), W held: %s:\n", slow ? "400 (the fake no faster)" : "900", ahead,
		       slow ? "about 48" : "56", slow ? "WallStop's ease, \"along the turn's arc (FaceArc), the straight rays meeting it too\", the front wheel's edge stopped short of it"
		                 : "WallStop's cut to 0% within a frame as before (inside the need of 400: met), \"along the turn's arc (FaceArc), the straight rays meeting it too\"");
		UpToSpeed(slow ? 400.0f : 0.0f);
		g_onFrame = WallFrame;
		g_glimpseTurn = 40.0f / DEG;
		RunFrames(600);
		int both0 = LogLines(bothWord);
		FakePlane *rail = RaisedRail(edge + ahead, 0.0f);
		g_wallGapLeast = 1e9f;
		g_wallSlopeWatch = 0.0f;
		GlimpseWatch(rail, 0.0f, 0.02f);
		RunFrames(40);
		float early = g_glimpseLeast;
		RunFrames(3000);
		float still = AlongStill(), rate = NthLineNumber(bothWord, both0, "the heading's rate ");
		int both = LogLines(bothWord) - both0;
		bool words = both >= 1 && NthLogLineHas(bothWord, both0, stopWord) && rate >= (slow ? 5.0f : 30.0f) && rate <= 50.0f;
		if (slow)   /* once stopped the heading follows the camera, 120 deg round by then, and the bike may ride off along the rail */
			CHECK(words && g_wallGapLeast > 0.0f, "\"... : WallStop); %s, the heading's rate %+.0f deg/s\" (%d), the front wheel's edge %.1f short of it at the closest (over 0)", bothWord, rate, both, g_wallGapLeast);
		else
			CHECK(words && NthLogLineHas(bothWord, both0, "the throttle eased to 0% (a stop from ") && early < 0.2f && still < 5.0f,
			      "\"...the throttle eased to 0%% (a stop from ... : WallStop); %s, the heading's rate %+.0f deg/s\" (%d), the input %.2f at the least in its first 0.02 s, stopped (%.1f in 0.25 s)", bothWord, rate, both, early,
			      still);
		g_onFrame = GlimpseFrame;
		DoneRiding();
	}
	RewriteIni("WallStopNarrow=0", "WallStopNarrow=40");
}

/* Review of the 2026-11-01a build: FaceArc's merge. (1) The same wall: turning right at 60 deg/s at 900 (the longer rays kept,
 * their arc turning about 64 deg over their reach), the speed held (no run-down, so the far wall stays where they meet it), a
 * wall across the heading that stays 670 ahead (WallStop's, seen by the longer rays along their arc about 650 past the front
 * wheel, past the need and its extra, 535: the throttle about half), then a post 100 across, another object ("FakePost"), on
 * the heading's line 200 past the front wheel, gone after 0.15 s: FaceLook's arc passes it about 20 to the right, so only the
 * straight rays meet it while WallStop eases the far wall. The post: FaceLook's ease, held to the far wall's (the build
 * before the review: "a wall already being eased: WallStop's", cut at once at the far wall's 535); the far wall's run kept
 * through it, so no fresh floor after (it would give all of the throttle again). (2) Turning hard at low speed: at 60, as
 * hard as the plugin lets it turn (about 58 deg/s), FaceLook's arc has turned 90 deg about 90 along, before the front wheel's
 * edge; a rail across the heading 20 past the front wheel: the straight verdict, WallStop's 0% (the need a wheel radius and
 * 10), not FaceLook's 87% (the build before, with no evidence the bike passes it). (3) An arc's slope and a straight wall: at 900 and 100 deg/s a ramp rising at 35 deg on
 * FaceLook's arc about 180 past the front wheel (under the climb limit: no verdict) and the post 20 across on the heading's line
 * 200 past it: the post FaceLook's ease (the build before: the ramp's no verdict, the post dropped, the throttle full). */
static float g_reviewAfter;   /* the input's most in the 0.2 s after the glimpse's plane went (in the frame: a loop of short RunFrames calls loses a sleep's movement at each, and the plugin's speed dips) */
static void ReviewFrame(float dt)
{
	GlimpseFrame(dt);
	if (g_glimpseW && !g_glimpseW->on && g_glimpseT <= g_glimpseFor + 0.2f) {
		float in = hypotf(MoveInput()[0], MoveInput()[1]);
		g_reviewAfter = in > g_reviewAfter ? in : g_reviewAfter;
	}
}
/* 2026-11-02a (the 2026-11-01a merge's open item 1: the ride sampled the far wall's input once, at the end of a fixed 500 ms, and
 * under two runs' load the far wall's ease had lapsed by then, 1.00): the far wall's input tracked in the frame hook, the post
 * placed there once WallStop's ease has held in the 0.15-0.68 band for 0.2 s running (1.5 s at most), with no read of the log
 * between. */
static float g_reviewHeld, g_reviewWaited, g_reviewFarIn, g_reviewPostAt;
static bool g_reviewPlaced, g_reviewHeldOk;
static uint8_t *g_reviewPostObj;
static void ReviewWaitFrame(float dt)
{
	if (g_reviewPlaced) {
		ReviewFrame(dt);
		return;
	}
	GlimpseFrame(dt);
	float in = hypotf(MoveInput()[0], MoveInput()[1]);
	g_reviewWaited += dt;
	g_reviewHeld = in >= 0.15f && in <= 0.68f ? g_reviewHeld + dt : 0.0f;
	if (g_reviewHeld >= 0.2f || g_reviewWaited >= 1.5f) {
		g_reviewHeldOk = g_reviewHeld >= 0.2f;
		g_reviewFarIn = in;
		g_reviewPostAt = g_reviewWaited;
		FakePlane *post = Obstacle(1, 99.6f + 29.9f + 200.0f, 60.0f, CAP_NONE, 10.0f, 1, g_reviewPostObj);
		post->bottom = 20.0f;
		post->halfWidth = 50.0f;
		GlimpseWatch(post, 0.15f, 0.05f);
		g_reviewAfter = 0.0f;
		g_reviewPlaced = true;
	}
}
static void WallFaceArcReviewTests(void)
{
	static const char wallAt[] = "rays: a wall ahead (", stopWord[] = ": WallStop)", longerWord[] = "), seen by the longer rays, ";
	static const char besideWord[] = "the straight rays only, beside the turn's arc: FaceLook's ease (FaceArc)", easedWord[] = "the straight rays only, beside the turn's arc, a wall already being eased: WallStop's (FaceArc)";
	static const char heldWord[] = "% by itself, held to WallStop's for the wall it is easing: FaceArc)";
	static uint8_t *postObj;
	float edge = 99.6f + 29.9f;
	if (!postObj)
		postObj = NewNode(*(void ***)g_wallObj, "FakePost", 0);   /* another object than FakeWall, the far wall's */
	RewriteIni("WallStopNarrow=40", "WallStopNarrow=0");   /* 2026-11-02a: 2026-11-01a's scenarios (a post 20 across among them) */

	printf("FaceArc (review: the same wall): turning right at 60 deg/s at 900, the speed held, a wall across the heading staying 670 ahead (WallStop's, by the longer rays along their arc), then a post 100 across "
	       "(FakePost) on the heading's line 200 past the front wheel, gone after 0.15 s (FaceLook's arc passes it on the right), W held: the post FaceLook's ease held to the far wall's, not WallStop's cut; no fresh floor after:\n");
	UpToSpeed(0.0f);
	g_glimpseTurn = 60.0f / DEG;
	RunFrames(500);
	g_fakeDecel = 1.0f;   /* the speed held */
	int long0 = LogLines(longerWord), beside0 = LogLines(besideWord), eased0 = LogLines(easedWord), held0 = LogLines(heldWord);   /* before: a pause while riding has the plugin's speed dip */
	FakePlane *farWall = Obstacle(0, 670.0f, 60.0f, CAP_NONE, 10.0f, 1, NULL);
	farWall->bottom = 20.0f;
	farWall->follow = 670.0f;
	g_reviewPostObj = postObj;   /* the post placed by the frame hook once the far wall's ease has held (2026-11-02a) */
	g_reviewHeld = g_reviewWaited = g_reviewPostAt = 0.0f;
	g_reviewPlaced = g_reviewHeldOk = false;
	g_onFrame = ReviewWaitFrame;   /* then, the post gone: the far wall's run again, or a fresh one with its floor */
	RunFrames(2000);
	g_onFrame = GlimpseFrame;
	float farIn = g_reviewFarIn, early = g_glimpseLeast, after = g_reviewAfter;
	int longs = LogLines(longerWord) - long0, beside = LogLines(besideWord) - beside0, eased = LogLines(easedWord) - eased0, helds = LogLines(heldWord) - held0;
	bool farArc = longs >= 1 && NthLogLineHas(longerWord, long0, "(WallStopReach), along the turn's arc, +");
	CHECK(farArc && g_reviewHeldOk && farIn >= 0.15f && farIn <= 0.68f,
	      "the far wall eased by WallStop, seen by the longer rays along the turn's arc (%d line(s)), the input in 0.15-0.68 for 0.2 s running (%s, %.2f s after the far wall went up), %.2f as the post went up",
	      longs, g_reviewHeldOk ? "yes" : "no, in 1.5 s", g_reviewPostAt, farIn);
	float postEase = NthLineNumber(besideWord, beside0, "the throttle eased to ");
	CHECK(beside >= 1 && eased == 0 && NthLogLineHas(besideWord, beside0, "(FakePost, layer 1)") && NthLogLineHas(besideWord, beside0, heldWord) && helds >= 1 && postEase <= farIn * 100.0f + 8.0f && early >= farIn - 0.12f && early >= 0.1f,
	      "the post: \"...(FakePost, layer 1), the throttle eased to %.0f%% (..%s); %s, ...\" (%d, %d held; %d \"%s\"), the far wall's %.0f%% or less; the input %.2f at the least in its first 0.05 s (the far wall's %.2f, "
	      "less 0.12; the build before: 0)", postEase, heldWord, besideWord, beside, helds, eased, easedWord, farIn * 100.0f, early, farIn);
	CHECK(after <= farIn + 0.15f && after >= 0.1f, "the far wall's run kept through the post: the input %.2f at the most in the 0.2 s after it went (the far wall's %.2f, and 0.15; a fresh floor: all of it)", after, farIn);
	farWall->follow = 0.0f;
	DoneRiding();

	printf("FaceArc (review: turning hard at low speed): turning right at 60 (the fake no faster) as hard as it lets (the camera at 120 deg/s), FaceLook's arc turned 90 deg about 90 along, before the front wheel's edge; a rail across the heading "
	       "20 past the front wheel, W held: the straight verdict, WallStop's 0%% (the need a wheel radius and 10), not FaceLook's 87%%:\n");
	UpToSpeed(60.0f);
	int wall0 = LogLines(wallAt), beside1 = LogLines(besideWord);
	g_glimpseTurn = 120.0f / DEG;
	RunFrames(800);
	FakePlane *rail = RaisedRail(edge + 20.0f, 0.0f);
	GlimpseWatch(rail, 0.1f, 0.05f);
	RunFrames(150);
	float rate = NthLineNumber(wallAt, wall0, "the heading's rate ");
	CHECK(NthLogLineHas(wallAt, wall0, "; the straight rays, the heading's rate ") && NthLogLineHas(wallAt, wall0, "the throttle eased to 0% (a stop from ") && NthLogLineHas(wallAt, wall0, stopWord) &&
	          LogLines(besideWord) == beside1 && g_glimpseLeast < 0.1f && rate >= 45.0f,
	      "\"rays: a wall ahead (..): .. the throttle eased to 0%% (a stop from .. %s; the straight rays, the heading's rate %+.0f deg/s\" (45 or more), no \"%s\" line (%d), the input %.2f at the least in its first 0.05 s (under 0.1; the build before: FaceLook's ease, 87%%, and that line)",
	      stopWord, rate, besideWord, LogLines(besideWord) - beside1, g_glimpseLeast);
	DoneRiding();

	printf("FaceArc (review: an arc's slope and a straight wall): turning right at 100 deg/s at 900, a ramp 120 across rising at 35 deg on FaceLook's arc about 180 past the front wheel (under the climb limit: no verdict) "
	       "and a post 20 across on the heading's line 200 past it, W held: the post FaceLook's ease, \"%s\" at 70-82%%, the input under 0.85 (the build before: the post dropped, the throttle full):\n", besideWord);
	UpToSpeed(0.0f);
	int beside2 = LogLines(besideWord), stop2 = LogLines(stopWord);
	g_glimpseTurn = 100.0f / DEG;
	RunFrames(500);
	float h = PlayerHeading();
	FakePlane *ramp = Obstacle(1, 250.0f, 60.0f, CAP_NONE, 10.0f, 1, NULL);
	ramp->point[0] += cosf(h) * 100.0f;   /* 100 to the right of the heading's line: the arc there, the straight rays 40 clear of it */
	ramp->point[1] -= sinf(h) * 100.0f;
	ramp->halfWidth = 60.0f;
	ramp->slant = 35.0f;
	FakePlane *post2 = RaisedRail(edge + 200.0f, 10.0f);
	GlimpseWatch(post2, 0.1f, 0.1f);
	RunFrames(150);
	ramp->on = false;
	int besides = LogLines(besideWord) - beside2, stops = LogLines(stopWord) - stop2;
	float eased2 = NthLineNumber(besideWord, beside2, "the throttle eased to ");
	CHECK(besides == 1 && stops == 0 && eased2 >= 70.0f && eased2 <= 82.0f && g_glimpseLeast < 0.85f,
	      "one \"..the throttle eased to %.0f%%..; %s, ..\" line (%d; 70-82), no WallStop line (%d), the input %.2f at the least in its first 0.1 s (under 0.85; the build before: full)", eased2, besideWord, besides, stops, g_glimpseLeast);
	DoneRiding();
	RewriteIni("WallStopNarrow=0", "WallStopNarrow=40");
}

/* WallStopClimb (2026-11-01a, test 47's 10 cuts by the longer rays forced straight and short while the climb's boost was on): the
 * boost on at a low log 8 across (ClimbHold=1.0 written for the rides, so it spans the approach), then a raised rail 650 past the
 * front wheel dead ahead, taken away after 0.5 s (it never comes within FaceLook's reach); and the rail first, a WallStop verdict
 * running, then the log: the boost let on. Each with WallStopClimb=0, the 2026-10-31a build, too. */
static void WallStopClimbTests(void)
{
	static const char wallAt[] = "rays: a wall ahead (90 deg): ", boostWords[] = "the climb limit 47 -> 85", cutWords[] = ": a wall ahead (the face rays' verdict)";
	float edge = 99.6f + 29.9f, cos85 = cosf(85.0f / DEG);
	RewriteIni("Climb=1\n", "Climb=1\nClimbHold=1.0\n");
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("WallStopClimb=1", "WallStopClimb=0");
		printf("WallStopClimb (test 47's 19:41:42, the APC): %sat 900 the climb's boost on at a low log 8 across, then a raised rail 650 past the front wheel dead ahead (gone after 0.5 s with the key on), W held: %s:\n",
		       off ? "WallStopClimb=0 written: " : "",
		       off ? "first seen 405 past the front wheel at most (the raw need, or FaceLook's reach), the input under 0.2 at once, as in the 2026-10-31a build"
		           : "first seen 600-655 past it by the longer rays with the boost on, the floor's 0.15 s over half the input, no cut, \"over it\" after");
		UpToSpeed(0.0f);
		g_onFrame = WallFrame;
		int wall0 = LogLines(wallAt), cut0 = LogLines(cutWords), over0 = LogLines("climb: over it after"), offText = LogLines("(while the climb's boost is on, that far when FaceLook's reach is shorter: WallStopClimb=0)");
		FakePlane *log = Obstacle(1, 150.0f, 8.0f, CAP_LOG, 8.0f, 1, NULL);   /* 8 across: met at 50 deg, over 47, climbed in a few frames, the bike keeping its speed (one 12 across held it under 150 for half a second) */
		log->round = true;
		float took = UntilBoost(cos85, 1000);
		RaisedRail(edge + 650.0f, 0.0f);
		g_wallSlopeMax = -1.0f;
		g_wallSlopeWatch = 0.15f;
		GlimpseWatch(g_stopW, off ? 0.0f : 0.5f, 0.15f);   /* on: gone before it could come within FaceLook's reach; off: left, till it is seen */
		float least = 9.0f;
		int ms = 0;
		while (LogLines(wallAt) == wall0 && ms < 1500) {
			RunFrames(10);
			ms += 10;
		}
		for (int t = 0; t < 5; t++) {
			RunFrames(10);
			float in = hypotf(MoveInput()[0], MoveInput()[1]);
			least = in < least ? in : least;
		}
		RunFrames(1800);
		float first = NthLogNumber(wallAt, wall0);
		int cuts = LogLines(cutWords) - cut0, overs = LogLines("climb: over it after") - over0;
		if (off)
			CHECK(offText == 1 && took > 0.0f && first <= 405.0f && least < 0.2f,
			      "the settings line \"(while the climb's boost is on, ...: WallStopClimb=0)\" (%d), the boost on (%.2f s), first seen %.0f past the front wheel (405 at most: at the raw need, or FaceLook's reach at the boost's "
			      "speed%s), the input %.2f at the least in the 0.05 s after (under 0.2)",
			      offText, took, first, NthLogLineHas(wallAt, wall0, ", looked for that far, past FaceLook's reach") ? ", \"looked for that far, past FaceLook's reach\"" : "", least);
		else {
			CHECK(took > 0.0f && first >= 600.0f && first <= 655.0f && NthLogLineHas(wallAt, wall0, "), seen by the longer rays, ") &&
			          NthLogLineHas(wallAt, wall0, "0.15 s of the speed for a wall first seen past FaceLook's reach (WallStopPersist)") && TraceAfterHas(wallAt, wall0, "| climb 85 for "),
			      "the boost on at the log (%.2f s), the rail first seen %.0f past the front wheel (600-655), \"...(WallStopPersist), seen by the longer rays, ... (WallStopReach)...\", the trace then \"climb 85 for\"", took, first);
			/* The floor of the rail seen at 600-655 (the watch starts as it is placed, the frame it is seen). The cut's absence and
			 * the input alone would pass in the 2026-10-31a build too (its rays never reach the rail in the watch, nor while the
			 * capsule is on the log). */
			CHECK(first >= 600.0f && first <= 655.0f && Near(g_wallSlopeMax, cos85) && g_glimpseLeast >= 0.5f && cuts == 0 && overs == 1,
			      "the rail seen at %.0f (600-655), the boost on throughout the floor's first 0.15 s (the limit's loosest cos %.4f, cos 85 %.4f), the input %.2f at the least then (0.5 or more), "
			      "no \"climb: cut after ...%s\" line (%d), \"climb: over it after\" (%d)", first, g_wallSlopeMax, cos85, g_glimpseLeast, cutWords, cuts, overs);
		}
		g_onFrame = GlimpseFrame;
		DoneRiding();
		if (off)
			RewriteIni("WallStopClimb=0", "WallStopClimb=1");
	}
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("WallStopClimb=1", "WallStopClimb=0");
		printf("WallStopClimb: %sat 900 a raised rail 650 past the front wheel first (a WallStop verdict running), then a low log 12 across 150 ahead, W held: %s:\n", off ? "WallStopClimb=0 written: " : "",
		       off ? "no boost while the rail's verdict stands (CLIMB_WALL), as in the 2026-10-31a build" : "the boost on at the log (\"the climb limit 47 -> 85\")");
		UpToSpeed(0.0f);
		int boost0 = LogLines(boostWords);
		RaisedRail(edge + 650.0f, 0.0f);
		RunFrames(30);
		FakePlane *log = Obstacle(1, 150.0f, 12.0f, CAP_LOG, 12.0f, 1, NULL);
		log->round = true;
		RunFrames(250);
		int boosts = LogLines(boostWords) - boost0;
		if (off)
			CHECK(boosts == 0, "no boost line (%d)", boosts);
		else
			CHECK(boosts == 1, "one \"%s\" line (%d; 2026-10-31a: none, the rail's far verdict a wall for the climb)", boostWords, boosts);
		DoneRiding();
		if (off)
			RewriteIni("WallStopClimb=0", "WallStopClimb=1");
	}
	RewriteIni("Climb=1\nClimbHold=1.0\n", "Climb=1\n");
}

/* A wooden road barrier on legs (test 47's 19:46): a beam 14 to 27 over the ground and 10 deep, its face 400 ahead, its line `turn`
 * off square (TurnPlane: 72 is 18 deg off the heading); under it two legs to 14, 8 wide, their feet 1 in front of its face and
 * their faces leaning toward the bike as they rise (slant 107: the climb rays at 4 and 10 read 107 deg square and about 135 at 18
 * deg, as the barriers read 105 to 114 at 10-30 deg), the first where the heading's line meets it at 7 over the ground, the second
 * 120 to the right along its line. The beam's underside at 14, not the design's 12: at 18 deg the front wheel rides over the beam
 * before the capsule meets it, and the climb rays, pitched 2 deg up by it, met nothing at 10 under a 12. */
static FakePlane *LegsBarrier(float turn)
{
	float h = PlayerHeading(), f[2] = { sinf(h), cosf(h) }, rt[2] = { cosf(h), -sinf(h) }, lean = -1.0f / tanf(107.0f / DEG);
	FakePlane *beam = Obstacle(0, 400.0f, 27.0f, CAP_STEP, 10.0f, 1, NULL);
	beam->bottom = 14.0f;
	beam->halfWidth = 150.0f;
	g_planeTopDepth[0] = 10.0f;
	if (turn != 0.0f)
		TurnPlane(beam, turn);
	float n[2] = { beam->normal[0], beam->normal[1] }, t[2] = { -n[1], n[0] };
	if (t[0] * rt[0] + t[1] * rt[1] < 0.0f) {
		t[0] = -t[0];
		t[1] = -t[1];
	}
	float pb = (PlayerPos()[0] - beam->point[0]) * n[0] + (PlayerPos()[1] - beam->point[1]) * n[1], fn = f[0] * n[0] + f[1] * n[1];
	float x = (1.0f + 7.0f * lean - pb) / fn, q[2] = { PlayerPos()[0] + f[0] * x, PlayerPos()[1] + f[1] * x };
	float a = (q[0] - beam->point[0]) * t[0] + (q[1] - beam->point[1]) * t[1];
	for (int i = 1; i < 3; i++) {
		FakePlane *leg = &g_planes[i];
		memset(leg, 0, sizeof(*leg));
		float along = a + (i == 2 ? 120.0f : 0.0f);
		leg->point[0] = beam->point[0] + n[0] + t[0] * along;
		leg->point[1] = beam->point[1] + n[1] + t[1] * along;
		leg->normal[0] = n[0];
		leg->normal[1] = n[1];
		leg->layer = 1;
		leg->top = 14.0f;
		leg->slant = 107.0f;
		leg->halfWidth = 4.0f;
		leg->on = true;
		g_capKind[i] = CAP_NONE;
		g_planeTopDepth[i] = 0.0f;
	}
	return beam;
}

/* ClimbLegs (2026-11-01a, test 47's wooden road barriers met at 10-30 deg, climbed as logs): the barrier on legs met square and at
 * 18 deg (held, no boost; ClimbLegs=0: "round, receding toward its foot" and the boost, the 2026-10-31a build), and a round log 25
 * across met at 30 and at 18 deg (climbed: its face solid at 4 to either side, not legs). ClimbMaxTop=18 for them (the legs test
 * goes with its judgement), put back to the 0 the run starts with after. */
static void WallLegsTests(void)
{
	static const char boostWords[] = "the climb limit 47 -> 85", legsWords[] = ": round at its foot but on legs (the ray 36 to the ", refusedWords[] = "not climbed: a beam on legs: something at 18 above the feet ";
	static const char roundWords[] = "ahead: round, receding toward its foot (ClimbMaxTop)", solidWords[] = "; solid at 4 to either side across its face, not on legs (ClimbLegs)";
	float cos85 = cosf(85.0f / DEG);
	g_onFrame = ClimbFrame;
	RewriteIni("ClimbMaxTop=0", "ClimbMaxTop=18");
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	CHECK(LogLines("; a face round at its foot (100 to 145 deg) climbed as a log only if the rays two capsule radii to either side across it meet it at 4 wherever they meet it higher (ClimbLegs: a log, not a beam on legs)") >= 1,
	      "the climb's settings line with ClimbMaxTop=18: \"...; a face round at its foot (100 to 145 deg) climbed as a log only if ... (ClimbLegs: a log, not a beam on legs)\"");
	g_capSlip = 0.0f;   /* held at it, stalled: its refusal's line */
	for (int k = 0; k < 3; k++) {
		bool off = k == 1;
		float turn = k == 2 ? 72.0f : 0.0f;
		if (off) {
			RewriteIni("ClimbLegs=145", "ClimbLegs=0");
			GetOffAndOn(45.0f);
			g_camYaw = PlayerHeading();
		} else if (k == 2) {
			RewriteIni("ClimbLegs=0", "ClimbLegs=145");
			GetOffAndOn(45.0f);
			g_camYaw = PlayerHeading();
		}
		printf("ClimbLegs (test 47's 19:46): %sa wooden road barrier on legs 400 ahead (a beam 14 to 27 over the ground, its legs leaning to 107 deg at their foot), %s, W held 4 s: %s:\n",
		       off ? "ClimbLegs=0 written: " : "", k == 2 ? "its line 18 deg off the heading" : "met square",
		       off ? "\"round, receding toward its foot (ClimbMaxTop)\", the boost on, as in the 2026-10-31a build" : k == 2 ? "no boost, held, one \"round at its foot but on legs\" line"
		           : "no boost, held at the beam, one \"round at its foot but on legs\" line, \"not climbed: a beam on legs\" once stalled");
		int boost0 = LogLines(boostWords), legs0 = LogLines(legsWords), refused0 = LogLines(refusedWords), round0 = LogLines(roundWords), offText = LogLines("; a face round at its foot climbed as a log without asking (ClimbLegs=0)");
		g_slopeMin = 1.0f;
		FakePlane *beam = LegsBarrier(turn);
		if (off) {
			float took = UntilBoost(cos85, 4000);
			CHECK(offText == 1 && took > 0.0f && LogLines(roundWords) - round0 >= 1 && LogLines(legsWords) == legs0,
			      "the settings line \"...(ClimbLegs=0)\" (%d), the boost on (%.2f s), \"%s\" (%d), no legs line", offText, took, roundWords, LogLines(roundWords) - round0);
		} else {
			Keys(0.0f, 1.0f);
			RunFrames(4000);
			int boosts = LogLines(boostWords) - boost0, legs = LogLines(legsWords) - legs0, refused = LogLines(refusedWords) - refused0;
			CHECK(Near(g_slopeMin, COS47) && boosts == 0 && FaceGap(beam) > 17.0f, "no boost (the steepest limit %.2f deg, %d boost line), held at the beam (the axis %.1f from its face)", acosf(g_slopeMin) * DEG, boosts, FaceGap(beam));
			if (k == 0) {
				CHECK(legs == 1 && NthLogLineHas(legsWords, legs0, "left across its face passes under it at 4, meets it at 18; ClimbLegs): not climbed") && NthLogLineHas(legsWords, legs0, " deg), nothing at 31.9 within "),
				      "one \"climb: a low face at the capsule (...): ... (107 deg) ...%sleft across its face passes under it at 4, meets it at 18; ClimbLegs): not climbed\" line (%d)", legsWords, legs);
				CHECK(refused == 1 && NthLogLineHas(refusedWords, refused0, "(ClimbLegs)"), "stalled: one \"climb: stopped with forward held (...): %s... (ClimbLegs)\" line (%d)", refusedWords, refused);
			} else
				CHECK(legs >= 1 && NthLogLineHas(legsWords, legs0, "meets it at 18; ClimbLegs): not climbed"), "%d \"%s... meets it at 18; ClimbLegs): not climbed\" line(s)", legs, legsWords);
		}
		RollOff();
	}
	g_capSlip = 1.0f;
	float passed[2];
	int solid[2], legs[2], boosts[2];
	for (int k = 0; k < 2; k++) {
		float turn = k ? 72.0f : 60.0f;
		printf("ClimbLegs: a round log 25 across 600 ahead, its line %s deg off the heading, W held: the boost on, the side rays at 4 meeting it: not legs%s:\n", k ? "18" : "30",
		       k ? " (over it not asked: the fake's capsule, met this shallowly, slides along it once the boost lapses, ClimbLegs or not)" : ", over it");
		GetOffAndOn(45.0f);
		g_camYaw = PlayerHeading();
		int solid0 = LogLines(solidWords), legs0 = LogLines(legsWords), boost0 = LogLines(boostWords);
		FakePlane *w = Obstacle(0, 600.0f, 25.0f, CAP_LOG, 25.0f, 1, NULL);
		w->round = true;
		TurnPlane(w, turn);
		passed[k] = RideAt(w, 25.0f, k ? 2500 : 5000);
		solid[k] = LogLines(solidWords) - solid0;
		boosts[k] = LogLines(boostWords) - boost0;
		legs[k] = LogLines(legsWords) - legs0;
		RollOff();
	}
	CHECK(passed[0] > 0.0f && boosts[0] >= 1 && boosts[1] >= 1 && solid[0] >= 1 && solid[1] >= 1 && legs[0] == 0 && legs[1] == 0,
	      "the boost on at both (%d, %d), its line \"...%s\" (%d at 30 deg, %d at 18), no legs line (%d, %d), over it at 30 deg within 5 s (%.2f s)", boosts[0], boosts[1], solidWords, solid[0], solid[1],
	      legs[0], legs[1], passed[0]);
	RewriteIni("ClimbMaxTop=18", "ClimbMaxTop=0");
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
}
/* WallStopNarrow (2026-11-02a; test 48's mailboxes at the curves, 18:34:09 to 18:37:11: the longer rays' arc swept onto a mailbox
 * beside the curve 280-360 past the front wheel, inside the need, and WallStop cut the throttle to 0% at once; the capsule then
 * passed it within 6-48). Each ride at 900 (the fake's front wheel's edge 129.5 ahead of the axis, FaceLook's span 275, the need
 * 400) with WallStopNarrow=40 unless said; a ride with WallStopNarrow=0 written is 2026-11-01a's. */
static float g_nwFarLeast, g_nwNearMost, g_nwAtSpeed, g_nwT, g_nwLatchMost;
static FakePlane *g_nwPost;
static void NarrowFrame(float dt)   /* a post dead ahead: the input's least while it is over 300 past the front wheel, its most within 100, the speed as the front wheel's edge gets to it */
{
	GlimpseFrame(dt);
	if (!g_stopW || !g_stopW->on)
		return;
	float gap = FaceGap(g_stopW) - (99.6f + 29.9f), in = hypotf(MoveInput()[0], MoveInput()[1]);
	if (gap > 300.0f && in < g_nwFarLeast)
		g_nwFarLeast = in;
	if (gap > 0.0f && gap <= 100.0f && in > g_nwNearMost)
		g_nwNearMost = in;
	if (g_nwAtSpeed < 0.0f && gap <= 1.0f)
		g_nwAtSpeed = g_fakeSpeedNow;
}
static void LatchFrame(float dt)   /* the latch: the rail made a post (halfWidth 10, the same plane and object) 0.1 s on; the input's most from 0.2 to 0.45 s */
{
	GlimpseFrame(dt);
	if (!g_nwPost)
		return;
	g_nwT += dt;
	if (g_nwT >= 0.1f && g_nwPost->halfWidth == 0.0f)
		g_nwPost->halfWidth = 10.0f;
	float in = hypotf(MoveInput()[0], MoveInput()[1]);
	if (g_nwT >= 0.2f && g_nwT <= 0.45f && in > g_nwLatchMost)
		g_nwLatchMost = in;
}
/* The most "N past the front wheel" among the lines with `text`, from the (from + 1)-th on (-1e9: none). */
static float MostPast(const char *text, int from)
{
	float most = -1e9f;
	for (int i = from, n = LogLines(text); i < n; i++) {
		float v = NthLineNumber(text, i, " deg): ");
		most = v > most ? v : most;
	}
	return most;
}
/* Plane i a raised rail as RaisedRail's, `dist` from the axis along the heading `ah` (rad), facing back along it. */
static FakePlane *RailAlong(int i, float dist, float ah, float halfWidth, uint32_t layer)
{
	FakePlane *w = Obstacle(i, dist, 60.0f, CAP_NONE, 10.0f, layer, NULL);
	w->point[0] = PlayerPos()[0] + sinf(ah) * dist;
	w->point[1] = PlayerPos()[1] + cosf(ah) * dist;
	w->normal[0] = -sinf(ah);
	w->normal[1] = -cosf(ah);
	w->bottom = 20.0f;
	w->halfWidth = halfWidth;
	return w;
}
static void WallNarrowTests(void)
{
	static const char wallAt[] = "rays: a wall ahead (", stopWord[] = ": WallStop)", longerWord[] = "), seen by the longer rays, ";
	static const char narrowWord[] = "(narrow: the rays 40 to either side of its path pass it: FaceLook's ease, not WallStop's (WallStopNarrow))";
	static const char wideBoth[] = "(wide: the rays 40 to either side of its path meet it, the left ", movedWord[] = "(the verdict moved: the last line had FakeWall at ";
	float edge = 99.6f + 29.9f;
	g_onFrame = GlimpseFrame;

	/* 1, 2: the longer rays' first chord turning right at 50 deg/s (their reach the need, its extra and FaceLook's span past the
	 * front wheel, two chords, the first's heading half its turn on: h + k ds / 2), a thing popped onto it 300 past the front
	 * wheel (inside the need: no floor, test 48's 18:34:09 deterministically, no sweep's timing), on for 0.05 s. */
	for (int k = 0; k < 3; k++) {
		bool off = k == 1, wide = k == 2;
		if (off)
			RewriteIni("WallStopNarrow=40", "WallStopNarrow=0");
		printf("WallStopNarrow (test 48's 18:34:09): %sturning right at 50 deg/s at 900, %s popped onto the longer rays' first chord 300 past the front wheel (inside the need), for 0.05 s, W held: %s:\n",
		       off ? "WallStopNarrow=0 written: " : "", wide ? "a raised rail across the chord" : "a post 20 across",
		       off ? "\"eased to 0%\", seen by the longer rays, WallStop's cut at once, as in 2026-11-01a"
		       : wide ? "wide: WallStop's cut as before, its line \"(wide: the rays 40 to either side of its path meet it, ...: WallStopNarrow)\""
		              : "narrow: no WallStop line, \"(narrow: the rays 40 to either side of its path pass it: FaceLook's ease, not WallStop's (WallStopNarrow))\", the input kept");
		UpToSpeed(0.0f);
		int wall0 = LogLines(wallAt), stop0 = LogLines(stopWord), narrow0 = LogLines(narrowWord), long0 = LogLines(longerWord), wide0 = LogLines(wideBoth);   /* before: a read while riding has the plugin's speed dip, and the chords with it */
		g_glimpseTurn = 50.0f / DEG;
		RunFrames(500);
		float v = g_fakeSpeedNow, kk = (50.0f / DEG) / v, need = v * v / 2700.0f + 0.1f * v + 10.0f, reach = edge + need + 0.15f * v + 0.3f * v + 5.0f;
		float ah = PlayerHeading() + kk * 0.25f * reach;   /* the first of two chords: half of its own turn on */
		FakePlane *post = RailAlong(0, edge + 300.0f, ah, wide ? 0.0f : 10.0f, 1);
		g_stopW = NULL;
		GlimpseWatch(post, 0.05f, 0.05f);
		RunFrames(150);
		int walls = LogLines(wallAt) - wall0, stops = LogLines(stopWord) - stop0, narrows = LogLines(narrowWord) - narrow0, longs = LogLines(longerWord) - long0, wides = LogLines(wideBoth) - wide0;
		float first = NthLineNumber(wallAt, wall0, " deg): "), eased = NthLineNumber(wallAt, wall0, "the throttle eased to ");
		if (off)
			CHECK(stops >= 1 && longs >= 1 && eased == 0.0f && NthLogLineHas(wallAt, wall0, stopWord) && !NthLogLineHas(wallAt, wall0, "till it has stayed") && narrows == 0 && g_glimpseLeast < 0.2f,
			      "\"...%.0f past the front wheel ..., the throttle eased to %.0f%% (a stop from %.0f needs ..., seen by the longer rays, ...: WallStop)\" (%d WallStop, %d longer-ray line(s); no floor, no narrow line), the input %.2f at the least in 0.05 s (under 0.2)",
			      first, eased, v, stops, longs, g_glimpseLeast);
		else if (wide)
			CHECK(stops >= 1 && wides >= 1 && eased == 0.0f && NthLogLineHas(wallAt, wall0, wideBoth) && NthLogLineHas(wallAt, wall0, stopWord) && narrows == 0 && g_glimpseLeast < 0.2f,
			      "\"...the throttle eased to %.0f%% (a stop from ...: WallStop) %s...: WallStopNarrow)\" (%d), no narrow line (%d), the input %.2f at the least in 0.05 s (under 0.2: the cut kept)", eased, wideBoth, wides, narrows,
			      g_glimpseLeast);
		else
			CHECK(stops == 0 && walls >= 1 && narrows >= 1 && NthLogLineHas(wallAt, wall0, narrowWord) && eased >= 95.0f && first >= 270.0f && first <= 305.0f && g_glimpseLeast >= 0.88f,
			      "no WallStop line (%d), \"rays: a wall ahead (90 deg): %.0f past the front wheel ..., the throttle eased to %.0f%% %s\" (%d), the input %.2f at the least in its 0.05 s (0.88 or more: FaceLook's ease as it nears; 2026-11-01a: 0)",
			      stops, first, eased, narrowWord, narrows, g_glimpseLeast);
		DoneRiding();
		if (off)
			RewriteIni("WallStopNarrow=0", "WallStopNarrow=40");
	}

	/* 3: a post dead ahead, ridden straight at: FaceLook's ease as it nears, to nothing at the front wheel's edge, which gets to it
	 * at a crawl (the trade-off: it is bumped); 0: WallStop's, stopped a wheel radius and 10 short. */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("WallStopNarrow=40", "WallStopNarrow=0");
		printf("WallStopNarrow: %sa post 20 across 1100 ahead at 900, no turn, W held: %s:\n", off ? "WallStopNarrow=0 written: " : "",
		       off ? "WallStop's: stopped a wheel radius and 10 short of it, as in 2026-11-01a" : "first seen by the longer rays, narrow, 100%; the input full till it is 300 past the front wheel, then FaceLook's ease; not stopped short: the front wheel's edge gets to it");
		UpToSpeed(0.0f);
		g_onFrame = NarrowFrame;
		int wall0 = LogLines(wallAt), stop0 = LogLines(stopWord), narrow0 = LogLines(narrowWord);
		g_nwFarLeast = 9.0f;
		g_nwNearMost = -1.0f;
		g_nwAtSpeed = -1.0f;
		RaisedRail(1100.0f, 10.0f);
		RunFrames(off ? 3500 : 2000);
		g_onFrame = GlimpseFrame;
		int stops = LogLines(stopWord) - stop0, narrows = LogLines(narrowWord) - narrow0;
		float first = NthLineNumber(wallAt, wall0, " deg): "), eased = NthLineNumber(wallAt, wall0, "the throttle eased to ");
		if (off) {
			float still = AlongStill();
			CHECK(stops >= 1 && narrows == 0 && g_stopLeast > 20.0f && still < 5.0f, "%d WallStop line(s), no narrow line (%d), the front wheel's edge %.1f short of it at the closest, stopped (%.1f in 0.25 s)", stops, narrows, g_stopLeast, still);
		} else {
			float stopAt = MostPast(stopWord, stop0);
			CHECK(stopAt <= 0.0f && narrows >= 1 && NthLogLineHas(wallAt, wall0, narrowWord) && !NthLogLineHas(wallAt, wall0, "a stop from") && eased >= 99.0f && first >= 700.0f,
			      "no WallStop line while it is ahead of the front wheel's edge (%d, the furthest %.0f past it), the first \"rays: a wall ahead (90 deg): %.0f past the front wheel ..., the throttle eased to %.0f%% %s\" (%d narrow line(s))",
			      stops, stops ? stopAt : 0.0f, first, eased, narrowWord, narrows);
			CHECK(g_nwFarLeast >= 0.95f && g_nwNearMost >= 0.0f && g_nwNearMost < 0.8f && g_stopLeast <= 3.0f && g_nwAtSpeed >= 0.0f,
			      "the input %.2f at the least while it was over 300 past the front wheel (0.95 or more), %.2f at the most within 100 of it (under 0.8: FaceLook's ease), the front wheel's edge %.1f from it at the closest (3 or less: got to it, at %.0f a second; "
			      "2026-11-01a: stopped a wheel radius and 10 short)", g_nwFarLeast, g_nwNearMost, g_stopLeast, g_nwAtSpeed);
		}
		DoneRiding();
		if (off)
			RewriteIni("WallStopNarrow=0", "WallStopNarrow=40");
	}

	/* 4: the latch: a raised rail 600 ahead (470 past the front wheel: the longer rays', the floor), found wide; 0.1 s on the same
	 * plane (the same object) made a post 20 across: wide still for half a second from when it was found so, then narrow. */
	printf("WallStopNarrow (the latch): a raised rail 600 ahead at 900, W held, made a post 20 across (the same object) 0.1 s on: wide, WallStop's, for half a second from when it was found so; then narrow:\n");
	{
		UpToSpeed(0.0f);
		int wall0 = LogLines(wallAt), narrow0 = LogLines(narrowWord), wide0 = LogLines(wideBoth), latched0 = LogLines(" s ago: WallStopNarrow)");
		g_nwT = 0.0f;
		g_nwLatchMost = -1.0f;
		g_nwPost = RaisedRail(600.0f, 0.0f);
		g_onFrame = LatchFrame;
		RunFrames(450);
		int narrowsEarly = LogLines(narrowWord) - narrow0;
		RunFrames(500);
		g_onFrame = GlimpseFrame;
		g_nwPost = NULL;
		int narrows = LogLines(narrowWord) - narrow0, wides = LogLines(wideBoth) - wide0, latched = LogLines(" s ago: WallStopNarrow)") - latched0;
		CHECK(NthLogLineHas(wallAt, wall0, wideBoth) && NthLogLineHas(wallAt, wall0, stopWord) && wides >= 1 && narrowsEarly == 0 && g_nwLatchMost >= 0.0f && g_nwLatchMost < 0.2f && narrows >= 1,
		      "the first line WallStop's and wide (\"%s...\", %d), no narrow line in the first 0.45 s (%d), the input %.2f at the most 0.2-0.45 s on (under 0.2: WallStop's verdict stands; %d \"(wide: found so .. s ago: WallStopNarrow)\" line(s)), then a narrow line (%d)",
		      wideBoth, wides, narrowsEarly, g_nwLatchMost, latched, narrows);
		DoneRiding();
	}

	/* 5: what the side rays meet beside a post: an actor's capsule (layer 30) is passed; a solid thing makes it wide. */
	printf("WallStopNarrow: a post 20 across 300 ahead at 900 (170 past the front wheel), a plane 20 across 40 to its right: an actor's (layer 30): narrow; the same plane solid (layer 1): wide, WallStop's:\n");
	{
		UpToSpeed(0.0f);
		float h = PlayerHeading();
		int narrow0 = LogLines(narrowWord), oneSide0 = LogLines("(wide: the ray 40 to the right meets it ");
		RailAlong(0, 300.0f, h, 10.0f, 1);
		FakePlane *beside = RailAlong(1, 300.0f, h, 10.0f, 30);
		beside->point[0] += cosf(h) * 40.0f;
		beside->point[1] -= sinf(h) * 40.0f;
		GlimpseWatch(&g_planes[0], 0.05f, 0.05f);
		RunFrames(100);
		g_planes[1].on = false;
		int narrows = LogLines(narrowWord) - narrow0;
		RunFrames(900);
		h = PlayerHeading();
		RailAlong(0, 300.0f, h, 10.0f, 1);
		beside = RailAlong(1, 300.0f, h, 10.0f, 1);
		beside->point[0] += cosf(h) * 40.0f;
		beside->point[1] -= sinf(h) * 40.0f;
		GlimpseWatch(&g_planes[0], 0.05f, 0.05f);
		RunFrames(100);
		int oneSide = LogLines("(wide: the ray 40 to the right meets it ") - oneSide0;
		CHECK(narrows >= 1 && oneSide >= 1, "beside an actor's plane: %d narrow line(s); beside a solid one: %d \"(wide: the ray 40 to the right meets it .., the one to the left passes: WallStopNarrow)\" line(s)", narrows, oneSide);
		DoneRiding();
	}

	/* 6: the log fix (test 48's 18:37:15, 737 -> 136 with no 0% line: the line had the mailbox at 100%, the run then cut on the same
	 * wall): a raised rail 600 ahead (470 past the front wheel, between the need and its extra: WallStopPersist's floor, then the
	 * cut), the first line by the floor, then one more line as the run's ease on the same wall is cut under a fifth; 2026-11-01a:
	 * none till the second's rule. */
	printf("WallStop's lines (test 48's 18:37:15): a raised rail 600 ahead at 900, W held: the first line by the floor (80%% or more), then within 0.9 s one \"(the verdict moved: the last line had FakeWall at ..)\" line under 20%%:\n");
	{
		UpToSpeed(0.0f);
		int wall0 = LogLines(wallAt), moved0 = LogLines(movedWord);
		RaisedRail(600.0f, 0.0f);
		RunFrames(900);
		int moves = LogLines(movedWord) - moved0;
		float firstEase = NthLineNumber(wallAt, wall0, "the throttle eased to "), movedEase = NthLineNumber(movedWord, moved0, "the throttle eased to "), was = NthLogNumber(movedWord, moved0);
		CHECK(firstEase >= 80.0f && moves == 1 && movedEase < 20.0f && was >= 80.0f && NthLogLineHas(movedWord, moved0, stopWord),
		      "the first line at %.0f%% (80 or more), %d \"...the throttle eased to %.0f%% (...: WallStop) ... %s%.0f%%)\" line(s) (1, under 20%%; 2026-11-01a: none)", firstEase, moves, movedEase, movedWord, was);
		DoneRiding();
	}

	/* 7: the settings line's words, on (the run's INI) and off (written 0 for rides above and WallFaceArcTests'). */
	CHECK(LogLines("a wall whose sides the rays 40 to either side of its path both pass (a post, a mailbox, a lamp, a sign) eased by FaceLook's own ease, never cut by WallStop, one found wide staying so for half a second (WallStopNarrow); ") >= 1 &&
	          LogLines("every wall WallStop's, however narrow (WallStopNarrow=0); ") >= 1,
	      "the steer settings line: \"a wall whose sides the rays 40 to either side of its path both pass (...) eased by FaceLook's own ease, never cut by WallStop, one found wide staying so for half a second (WallStopNarrow)\", and with 0 \"every wall WallStop's, however narrow (WallStopNarrow=0)\"");
	g_onFrame = ClimbFrame;
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
}

/* Mode 19 (2026-11-06a; test 49's head-on mailbox, 12:00:26.042, and the checker's finding 3): WallNarrowSame and WallNarrowHigh.
 * The planes' 3D a node of their own whose user data (+0x110) is a placed reference (a TESObjectREFR of its own), as a mailbox's
 * or a car's is; FakeWall (what NULL) has none, as precombined geometry. Each thing popped onto the straight path 300 past the
 * front wheel at 900 (inside the need: WallStop's cut at once if wide, no floor), for 0.05 s, W held, no turn. */
static uint8_t *g_n49Obj[8];
static uint8_t *RefThing(int i, const char *name)
{
	if (!g_n49Obj[i]) {
		static const char *refrNames[] = { ".?AVTESObjectREFR@@", ".?AVTESForm@@" };
		static const char *nodeNames[] = { ".?AVNiNode@@", ".?AVNiAVObject@@", ".?AVNiObject@@" };
		uint8_t *ref = (uint8_t *)NewObject(MakeClass(refrNames, 2), 0x200);
		ref[0x1A] = 0x40;
		*(uint32_t *)(ref + 0x14) = 0x0003A1B0u + (uint32_t)i;
		g_n49Obj[i] = NewNode(MakeClass(nodeNames, 3), name, 0);
		*(uint8_t **)(g_n49Obj[i] + 0x110) = ref;
	}
	return g_n49Obj[i];
}
/* Plane i a thing `ahead` of the axis along the heading, its centre `across` to the right of the line (- left), facing back,
 * from `bottom` to `top` over the ground, halfWidth along its line, its 3D `what` (NULL: FakeWall). */
static FakePlane *Thing49(int i, float ahead, float across, float halfWidth, float bottom, float top, uint8_t *what)
{
	float h = PlayerHeading();
	FakePlane *w = Obstacle(i, ahead, top, CAP_NONE, 10.0f, 1, what);
	w->point[0] += cosf(h) * across;
	w->point[1] -= sinf(h) * across;
	w->bottom = bottom;
	w->halfWidth = halfWidth;
	return w;
}
static void WallNarrowTests49(void)
{
	static const char wallAt[] = "rays: a wall ahead (", stopWord[] = ": WallStop)";
	float edge = 99.6f + 29.9f;
	g_onFrame = GlimpseFrame;
	printf("WallNarrowSame, WallNarrowHigh (2026-11-06a; test 49's mailbox and the checker's finding 3): the settings line:\n");
	CHECK(LogLines("a one-side hit on the wall's own reference, the ray 80 out passing, narrow (WallNarrowSame); the side rays at axle height and at 1.5 radii (WallNarrowHigh); ") >= 1,
	      "\"  steer (2026-11-06a): a one-side hit on the wall's own reference, the ray 80 out passing, narrow (WallNarrowSame); the side rays at axle height and at 1.5 radii (WallNarrowHigh); ...\"");
	/* 1-4: the mailbox (on, then WallNarrowSame=0), the car's corner, the post before a fence, the mailbox with no reference */
	for (int c = 0; c < 6; c++) {
		if (c == 3)
			continue;   /* (the car with WallNarrowSame=0: wide as well, by 2026-11-02a's rule; not ridden, mode 19's time) */
		bool off = c == 1;
		const char *name = c <= 1 ? "T1's mailbox (25 each side of its centre, 22 right of the line, its own reference)" : c <= 3 ? "a car's corner (70 each side, its left edge 20 left of the line, one reference)"
		                 : c == 4 ? "a post (10 each side, reference A) with a fence 40 to its right (reference B)" : "the mailbox with no reference (FakeWall)";
		if (off)
			RewriteIni("WallNarrowSame=1", "WallNarrowSame=0");
		printf("WallNarrowSame: %s%s popped 300 past the front wheel at 900 for 0.05 s, W held:\n", off ? "WallNarrowSame=0 written: " : "", name);
		UpToSpeed(0.0f);
		int wall0 = LogLines(wallAt), stop0 = LogLines(stopWord);
		float a = edge + 300.0f;
		FakePlane *w;
		if (c <= 1)
			w = Thing49(0, a, 22.0f, 25.0f, 0.0f, 60.0f, RefThing(0, "Tracker_002"));
		else if (c <= 3)
			w = Thing49(0, a, 50.0f, 70.0f, 0.0f, 60.0f, RefThing(1, "Sedan02_Postwar"));
		else if (c == 4) {
			w = Thing49(0, a, 0.0f, 10.0f, 0.0f, 60.0f, RefThing(2, "PostA"));
			Thing49(1, a, 40.0f, 10.0f, 0.0f, 60.0f, RefThing(3, "FenceWood01"));
		} else
			w = Thing49(0, a, 22.0f, 25.0f, 0.0f, 60.0f, NULL);
		g_stopW = NULL;
		GlimpseWatch(w, 0.05f, 0.05f);
		if (c == 4)
			g_planes[1].on = true;
		RunFrames(120);
		g_planes[1].on = false;
		int stops = LogLines(stopWord) - stop0;
		float eased = NthLineNumber(wallAt, wall0, "the throttle eased to ");
		if (c == 0)
			CHECK(stops == 0 && NthLogLineHas(wallAt, wall0, "(narrow: the ray 40 to the right meets it ") && NthLogLineHas(wallAt, wall0, ", its own reference ") && NthLogLineHas(wallAt, wall0, ", the one 80 out passes; the one to the left passes") &&
			          eased >= 95.0f && g_glimpseLeast >= 0.88f,
			      "no WallStop line (%d), the first \"rays: a wall ahead ...: the throttle eased to %.0f%% (narrow: the ray 40 to the right meets it ..., its own reference 0003A1B0, the one 80 out passes; the one to the left passes: ...)\", the input %.2f at the least in 0.05 s (0.88 or more; 2026-11-02a: wide, 0)",
			      stops, eased, g_glimpseLeast);
		else if (c == 1)
			CHECK(stops >= 1 && NthLogLineHas(wallAt, wall0, "(wide: the ray 40 to the right meets it ") && eased == 0.0f && g_glimpseLeast < 0.2f,
			      "\"...eased to %.0f%% (a stop ...: WallStop) (wide: the ray 40 to the right meets it ..., the one to the left passes: WallStopNarrow)\" (%d WallStop), the input %.2f at the least (under 0.2): 2026-11-02a", eased, stops, g_glimpseLeast);
		else if (c <= 3)
			CHECK(stops >= 1 && NthLogLineHas(wallAt, wall0, "(wide: ") && NthLogLineHas(wallAt, wall0, off ? "(wide: the ray 40 to the right meets it " : ", and the one 80 out too") && g_glimpseLeast < 0.2f,
			      "wide, WallStop's (%d), the line %s, the input %.2f at the least (under 0.2)", stops, off ? "\"(wide: the ray 40 to the right meets it ...\" (2026-11-02a)" : "\"... its own reference ..., and the one 80 out too ...\"", g_glimpseLeast);
		else if (c == 4)
			CHECK(stops >= 1 && NthLogLineHas(wallAt, wall0, "(wide: the ray 40 to the right meets FenceWood01 ") && NthLogLineHas(wallAt, wall0, ", another reference (0003A1B3)") && g_glimpseLeast < 0.2f,
			      "wide, WallStop's (%d): \"(wide: the ray 40 to the right meets FenceWood01 level with the hit, another reference (0003A1B3), the one to the left passes: WallStopNarrow)\", the input %.2f at the least (under 0.2)", stops, g_glimpseLeast);
		else
			CHECK(stops >= 1 && NthLogLineHas(wallAt, wall0, "(wide: the ray 40 to the right meets it ") && NthLogLineHas(wallAt, wall0, ", no reference, the one to the left passes") && g_glimpseLeast < 0.2f,
			      "wide as in 2026-11-02a (%d WallStop): \"(wide: the ray 40 to the right meets it level with the hit, no reference, the one to the left passes: WallStopNarrow)\", the input %.2f at the least (under 0.2)", stops, g_glimpseLeast);
		DoneRiding();
		if (off)
			RewriteIni("WallNarrowSame=0", "WallNarrowSame=1");
	}
	/* 4b (review DR1): a long one-reference face (a fence, a jersey barrier, a car's flank) 50 deg off square through the same point:
	 * on its nearer side the ray 40 out meets it 48 nearer, a straight face's 95 nearer at 80 out, before the side ray's own window
	 * (80 before the hit): the far ray's window moved by the side ray's 48 holds it, so it reads wide, WallStop's, as 2026-11-02a.
	 * The fake's planes are one-sided: a ray starting behind the face passes, as one starting behind a thin wall or inside a car. */
	printf("WallNarrowSame: a long face (its own reference) 50 deg off square popped 300 past the front wheel at 900 for 0.05 s, W held: wide, the far ray meeting it too (review DR1):\n");
	{
		UpToSpeed(0.0f);
		int wall0 = LogLines(wallAt), stop0 = LogLines(stopWord);
		FakePlane *w = Thing49(0, edge + 300.0f, 0.0f, 0.0f, 0.0f, 60.0f, RefThing(6, "JerseyBarrier01"));
		float c = cosf(50.0f / DEG), s = sinf(50.0f / DEG), nx = w->normal[0], ny = w->normal[1];
		w->normal[0] = nx * c - ny * s;
		w->normal[1] = nx * s + ny * c;
		g_stopW = NULL;
		GlimpseWatch(w, 0.05f, 0.05f);
		RunFrames(120);
		int stops = LogLines(stopWord) - stop0;
		CHECK(stops >= 1 && NthLogLineHas(wallAt, wall0, stopWord) && NthLogLineHas(wallAt, wall0, " nearer, its own reference 0003A1B6, and the one 80 out too, the one to the ") && g_glimpseLeast < 0.2f,
		      "\"...: WallStop) (wide: the ray 40 to the .. meets it .. nearer, its own reference 0003A1B6, and the one 80 out too, the one to the .. passes: WallStopNarrow)\" (%d WallStop), the input %.2f at the least (under 0.2; "
		      "the side ray's window for the far ray: narrow, FaceLook's ease)", stops, g_glimpseLeast);
		DoneRiding();
	}
	/* 5: finding 3's rail: a rail from 40 to 50 over the ground across the path (one reference) over a post (5 each side, the same
	 * reference, 0 to 40) on the line: the axle ray meets the post, the 1.5-radii ray the rail; the side rays pass between the posts
	 * at axle height and meet the rail at 1.5 radii: wide. WallNarrowHigh=0: narrow (2026-11-02a). */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("WallNarrowHigh=1", "WallNarrowHigh=0");
		printf("WallNarrowHigh: %sa rail 40 to 50 high across the path over a post 10 across (one reference) popped 300 past the front wheel at 900 for 0.05 s, W held: %s:\n", off ? "WallNarrowHigh=0 written: " : "",
		       off ? "narrow, FaceLook's ease (2026-11-02a)" : "wide at 1.5 radii, WallStop's cut");
		UpToSpeed(0.0f);
		int wall0 = LogLines(wallAt), stop0 = LogLines(stopWord), narrow0 = LogLines("(narrow: the rays 40 to either side of its path pass it");
		float a = edge + 300.0f;
		uint8_t *rail = RefThing(4, "GRailStrShort01");
		FakePlane *w = Thing49(0, a, 0.0f, 0.0f, 40.0f, 50.0f, rail);
		Thing49(1, a, 0.0f, 5.0f, 0.0f, 40.0f, rail);
		g_stopW = NULL;
		GlimpseWatch(w, 0.05f, 0.05f);
		g_planes[1].on = true;
		RunFrames(60);
		g_planes[1].on = false;
		RunFrames(60);
		int stops = LogLines(stopWord) - stop0, narrows = LogLines("(narrow: the rays 40 to either side of its path pass it") - narrow0;
		if (off)
			CHECK(stops == 0 && narrows >= 1 && g_glimpseLeast >= 0.88f, "no WallStop line (%d), a narrow line (%d), the input %.2f at the least (0.88 or more): 2026-11-02a", stops, narrows, g_glimpseLeast);
		else
			CHECK(stops >= 1 && NthLogLineHas(wallAt, wall0, "(wide: the rays 40 to either side of its path at 1.5 radii meet it") && NthLogLineHas(wallAt, wall0, stopWord) && narrows == 0 && g_glimpseLeast < 0.2f,
			      "\"...: WallStop) (wide: the rays 40 to either side of its path at 1.5 radii meet it, ...: WallStopNarrow)\" (%d WallStop), no narrow line (%d), the input %.2f at the least (under 0.2; 2026-11-02a: narrow, 0.88 or more)", stops, narrows,
			      g_glimpseLeast);
		DoneRiding();
		if (off)
			RewriteIni("WallNarrowHigh=0", "WallNarrowHigh=1");
	}
	CHECK(LogLines("any side hit wide (WallNarrowSame=0); ") >= 1 && LogLines("at axle height only (WallNarrowHigh=0); ") >= 1,
	      "the settings line with each 0: \"any side hit wide (WallNarrowSame=0); \" and \"at axle height only (WallNarrowHigh=0); \"");
}

/* The sidestep (2026-11-06a, Sidestep=40 rewritten for these rides): a thing ahead at 900, W held, the camera fixed (H0 its yaw).
 * SsFrame watches the heading's offset from H0 and its rate, the capsule's place across the old line (from where the ride's watch
 * began) and its least gap to the thing's edge as it passes it, the input's least. */
static float g_ssRateT, g_ssH0f, g_ssMostOff, g_ssMostRate, g_ssLastH, g_ssInLeast, g_ssGapLeast, g_ssLatAtPost, g_ssStartP[2], g_ssPostAlong, g_ssPostAcross, g_ssPostHalf, g_ssT, g_ssEvent;
static bool g_ssPassed, g_ssWatchOn;
static int g_ssEventKind;   /* 1: a side key at g_ssEvent s, 2: the camera turned 5 deg, 3: the brake key */
static void SsFrame(float dt)
{
	float h = PlayerHeading();
	if (g_ssWatchOn) {
		float off = remainderf(h - g_ssH0f, 6.2831853f) * DEG;
		if (fabsf(off) > g_ssMostOff)
			g_ssMostOff = fabsf(off);
		g_ssRateT += dt;
		if (g_ssRateT >= 0.04f) {   /* the rate over 0.04 s or more (a frame's own time is the fake's, the plugin's step its own) */
			float rate = fabsf(remainderf(h - g_ssLastH, 6.2831853f)) * DEG / g_ssRateT;
			if (rate > g_ssMostRate)
				g_ssMostRate = rate;
			g_ssLastH = h;
			g_ssRateT = 0.0f;
		}
		float in = hypotf(MoveInput()[0], MoveInput()[1]);
		if (in < g_ssInLeast)
			g_ssInLeast = in;
		float f[2] = { sinf(g_ssH0f), cosf(g_ssH0f) }, r[2] = { cosf(g_ssH0f), -sinf(g_ssH0f) };
		float dx = PlayerPos()[0] - g_ssStartP[0], dy = PlayerPos()[1] - g_ssStartP[1], along = dx * f[0] + dy * f[1], lat = dx * r[0] + dy * r[1];
		if (!g_ssPassed && along >= g_ssPostAlong) {
			g_ssPassed = true;
			g_ssLatAtPost = lat;
			g_ssGapLeast = fabsf(lat - g_ssPostAcross) - g_ssPostHalf;
		}
		g_ssT += dt;
		if (g_ssEventKind && g_ssT >= g_ssEvent) {
			if (g_ssEventKind == 1)
				Keys(1.0f, 1.0f);
			else if (g_ssEventKind == 2)
				g_camYaw += 5.0f / DEG;
			else
				g_testKeyHeld = true;
			g_ssEventKind = -g_ssEventKind;
		}
	}
	else
		g_ssLastH = h;
	GlimpseFrame(dt);
}
static void SsWatch(float postAlong, float postAcross, float half)
{
	g_ssH0f = g_camYaw;
	g_ssMostOff = g_ssMostRate = g_ssRateT = 0.0f;
	g_ssLastH = PlayerHeading();
	g_ssInLeast = 9.0f;
	g_ssGapLeast = 1e9f;
	g_ssLatAtPost = 0.0f;
	g_ssStartP[0] = PlayerPos()[0];
	g_ssStartP[1] = PlayerPos()[1];
	g_ssPostAlong = postAlong;
	g_ssPostAcross = postAcross;
	g_ssPostHalf = half;
	g_ssPassed = false;
	g_ssT = 0.0f;
	g_ssWatchOn = true;
	g_onFrame = SsFrame;
}
static void SidestepTests49(void)
{
	static const char startWord[] = "sidestep: ", overWord[] = "sidestep: over after ", letWord[] = "sidestep: let go after ", noneWord[] = "sidestep: none for ";
	float edge = 99.6f + 29.9f;
	printf("Sidestep (2026-11-06a; the tester's wish at test 49's mailbox): Sidestep=0 (2026-11-02a): a post 20 across (its own reference) dead ahead 800 past the front wheel at 900, W held: no sidestep, FaceLook's ease to it:\n");
	{
		UpToSpeed(0.0f);
		int ss0 = LogLines(startWord);
		Thing49(0, edge + 800.0f, 0.0f, 10.0f, 0.0f, 60.0f, RefThing(2, "PostA"));
		float least = 9999.0f;
		for (int i = 0; i < 30; i++) {
			RunFrames(50);
			if (g_fakeSpeedNow < least)
				least = g_fakeSpeedNow;
		}
		CHECK(LogLines(startWord) == ss0 && least < 300.0f && LogLines("no sidestep (Sidestep=0); ") >= 1, "no \"sidestep:\" line (%d), the speed %.0f at the least in 1.5 s (under 300: FaceLook's ease), the settings line \"no sidestep (Sidestep=0)\"",
		      LogLines(startWord) - ss0, least);
		DoneRiding();
	}
	RewriteIni("Sidestep=0", "Sidestep=40");
	/* 6: both open */
	printf("Sidestep=40 written: the same post dead ahead, and a car 280 right of the line 845 ahead (where a 40 deg/s arc would put the longer rays): to the right (both sides open, a square face, no turn), up to 12 deg at 40 deg/s, 60 across, back on a parallel line within 1.2 s, the input kept, no WallStop line (the longer rays along the old line):\n");
	{
		UpToSpeed(0.0f);
		int ss0 = LogLines(startWord), over0 = LogLines(overWord), narrow0 = LogLines("(narrow: the rays 40 to either side of its path pass it"), stop0 = LogLines(": WallStop)");
		Thing49(0, edge + 800.0f, 0.0f, 10.0f, 0.0f, 60.0f, RefThing(2, "PostA"));
		Thing49(1, 845.0f, 280.0f, 70.0f, 0.0f, 60.0f, RefThing(1, "Sedan02_Postwar"));
		SsWatch(edge + 800.0f, 0.0f, 10.0f);
		RunFrames(1300);
		float hAfter = fabsf(remainderf(PlayerHeading() - g_ssH0f, 6.2831853f)) * DEG;
		RunFrames(500);
		g_ssWatchOn = false;
		float overAfter = NthLogNumber(overWord, over0);
		CHECK(LogLines(startWord) - ss0 >= 2 && NthLogLineHas(startWord, ss0, "to the right, both sides open: the right, up to 12 deg at 40 deg/s for 60 across (Sidestep)") && LogLines("(narrow: the rays 40 to either side of its path pass it") > narrow0 &&
		          LogLines("a narrow thing ahead with no side key held and no turn asked stepped round toward its open side from 250 a second, up to 12 deg at 40 deg/s for 60 across, then back to the line (Sidestep); ") >= 1,
		      "\"sidestep: PostA (layer 1) narrow .. past the front wheel at ..: to the right, both sides open: the right, up to 12 deg at 40 deg/s for 60 across (Sidestep)\", after a narrow line; the settings line's words");
		CHECK(g_ssMostOff >= 9.0f && g_ssMostOff <= 12.5f && g_ssMostRate < 45.0f && overAfter < 1.2f && hAfter < 0.5f,
		      "the heading %.1f deg off the old line at the most (9-12.5), its rate %.0f deg/s at the most (under 45), \"sidestep: over after %.2f s\" (within 1.2), the heading %.2f deg off it after (within 0.5)", g_ssMostOff, g_ssMostRate, overAfter, hAfter);
		CHECK(g_ssPassed && g_ssLatAtPost >= 55.0f && g_ssLatAtPost <= 75.0f && g_ssGapLeast >= 18.0f + 5.0f && g_ssInLeast >= 0.9f && LogLines(": WallStop)") == stop0,
		      "past the post %.0f to the right of the old line (55-75), %.0f clear of its edge (the capsule's 18 and 5 or more), the input %.2f at the least (0.9 or more; 2026-11-02a: eased to it), no WallStop line for the car (%d)", g_ssLatAtPost,
		      g_ssGapLeast, g_ssInLeast, LogLines(": WallStop)") - stop0);
		DoneRiding();
	}
	/* 7: T1's mailbox, the right side met by its own reference: to the left */
	printf("Sidestep: T1's mailbox (25 each side, 22 right of the line, its own reference) 800 past the front wheel: to the left, the side its rays found open; past it on the left:\n");
	{
		UpToSpeed(0.0f);
		int ss0 = LogLines(startWord), over0 = LogLines(overWord);
		Thing49(0, edge + 800.0f, 22.0f, 25.0f, 0.0f, 60.0f, RefThing(0, "Tracker_002"));
		SsWatch(edge + 800.0f, 22.0f, 25.0f);
		RunFrames(1800);
		g_ssWatchOn = false;
		CHECK(NthLogLineHas(startWord, ss0, "to the left, the side its rays found open (the right one meets it, its own reference)") && LogLines(overWord) - over0 == 1 && g_ssPassed && g_ssLatAtPost < 0.0f && g_ssGapLeast >= 18.0f,
		      "\"sidestep: Tracker_002 ...: to the left, the side its rays found open (the right one meets it, its own reference), ...\", over (%d), past it %.0f left of the old line, %.0f clear of its edge (18 or more)",
		      LogLines(overWord) - over0, -g_ssLatAtPost, g_ssGapLeast);
		DoneRiding();
	}
	/* 8: the cancels */
	for (int c = 1; c <= 3; c++) {
		const char *what = c == 1 ? "a side key (forward and right) 0.15 s in" : c == 2 ? "the camera turned 5 deg 0.15 s in" : "the brake key 0.15 s in";
		printf("Sidestep: the post dead ahead, %s: let go at once, its line:\n", what);
		UpToSpeed(0.0f);
		g_testVk = 0x20;
		g_testKeyHeld = false;
		int ss0 = LogLines(startWord), let0 = LogLines(letWord);
		Thing49(0, edge + 800.0f, 0.0f, 10.0f, 0.0f, 60.0f, RefThing(2, "PostA"));
		SsWatch(edge + 800.0f, 0.0f, 10.0f);
		RunFrames(40);   /* the start (the post seen at once, the longer rays' reach) */
		g_ssT = 0.0f;
		g_ssEvent = 0.15f;
		g_ssEventKind = c;
		RunFrames(400);
		g_ssWatchOn = false;
		g_ssEventKind = 0;
		g_testKeyHeld = false;
		float after = NthLogNumber(letWord, let0);
		const char *word = c == 1 ? ": a side key (the capsule " : c == 2 ? ": the game's own target moved 5." : ": the brake key (the capsule ";
		CHECK(LogLines(startWord) - ss0 >= 2 && LogLines(letWord) - let0 == 1 && NthLogLineHas(letWord, let0, word) && (c != 2 || NthLogLineHas(letWord, let0, "(the mouse)")) && after >= 0.05f && after < 0.3f,
		      "\"sidestep: let go after %.2f s%s...\" (%d; 0.05-0.3 s: 0.15 s after the watch began, the start within its first frames)", after, word, LogLines(letWord) - let0);
		DoneRiding();
	}
	/* 9: the open side taken. 2026-11-24: 9 and 9b on the fake's fixed clock (Fixed66): which of the rays met the car and when is
	 * decided by where the bike was at the frames the plugin cast them, which on the machine's clock moved with the frames' lengths
	 * and the log read 0.4 s in (a frame's worth of time the plugin's speed saw and the world didn't): beside another mode both
	 * failed, nones 1 and starts 1 with the other words, and passed alone */
	Fixed66(true);
	printf("Sidestep: the post dead ahead with a car's back (its own reference, 30 each side) 60 to the right of the line 500 past the front wheel: \"none for\" the right, then the left taken; cars both sides: \"none for\" twice, no sidestep:\n");
	for (int k = 0; k < 2; k++) {
		UpToSpeed(0.0f);
		int ss0 = LogLines(startWord), none0 = LogLines(noneWord), let0 = LogLines("sidestep: PostA (layer 1) narrow ");
		Thing49(0, edge + 800.0f, 0.0f, 10.0f, 0.0f, 60.0f, RefThing(2, "PostA"));
		for (int s = 0; s <= k; s++)   /* a car's back, facing the bike, where the clear ray runs */
			Thing49(1 + s, edge + 500.0f, s ? -60.0f : 60.0f, 30.0f, 0.0f, 100.0f, RefThing(5, "StationWagon02"));
		RunFrames(400);   /* the cars still ahead (passed at about 0.7 s, when that side is clear again) */
		int nones = LogLines(noneWord) - none0, starts = LogLines("sidestep: PostA (layer 1) narrow ") - let0;
		RunFrames(k ? 300 : 1100);
		if (k == 0)
			CHECK(nones == 1 && NthLogLineHas(noneWord, none0, "the right (both open) is taken: the ray 60 to its right met StationWagon02 ") && starts == 1 &&
			          NthLogLineHas("sidestep: PostA (layer 1) narrow ", let0, "to the left, both sides open, the other one taken"),
			      "\"sidestep: none for PostA: the right (both open) is taken: the ray 60 to its right met StationWagon02 ..\" (%d), then \"... to the left, both sides open, the other one taken ...\" (%d)", nones, starts);
		else
			CHECK(nones == 2 && starts == 0 && LogLines(startWord) - ss0 >= 2, "\"sidestep: none for PostA\" twice (%d: the right, then the left), no sidestep while the cars are ahead (%d)", nones, starts);
		DoneRiding();
	}
	/* 9b (review DR2): the post dead ahead with, to the right, a guard rail along the path 35 out from 100 ahead on, or a car's flank
	 * 45 out from 150 behind to 250 ahead. Both side rays (40 out from the hit, parallel) pass it, the face is square and there is no
	 * turn: both open, the right tried first; the lane's ray 60 out runs past the rail, or starts inside the car (the fake's faces
	 * one-sided, as Havok's). The rays across to the lane meet it: the right taken, the left stepped to. */
	printf("Sidestep: the post dead ahead with a guard rail along the path 35 to the right from 100 ahead, then a car's flank 45 to the right abeam: \"none for\" the right (a ray across to its lane), then the left taken (review DR2):\n");
	for (int k = 0; k < 2; k++) {
		UpToSpeed(0.0f);
		int none0 = LogLines(noneWord), let0 = LogLines("sidestep: PostA (layer 1) narrow ");
		Thing49(0, edge + 800.0f, 0.0f, 10.0f, 0.0f, 60.0f, RefThing(2, "PostA"));
		FakePlane *by = Thing49(1, k ? 50.0f : 1100.0f, k ? 45.0f : 35.0f, k ? 200.0f : 1000.0f, 0.0f, k ? 100.0f : 60.0f, k ? RefThing(1, "Sedan02_Postwar") : RefThing(7, "GuardRail01"));
		float h = PlayerHeading();
		by->normal[0] = -cosf(h);   /* along the path, facing the bike (left) */
		by->normal[1] = sinf(h);
		SsWatch(edge + 800.0f, 0.0f, 10.0f);
		RunFrames(1800);
		g_ssWatchOn = false;
		int nones = LogLines(noneWord) - none0, starts = LogLines("sidestep: PostA (layer 1) narrow ") - let0;
		const char *word = k ? "the right (both open) is taken: the ray out 78 to its right met Sedan02_Postwar " : "the right (both open) is taken: the ray from the capsule's right edge to its lane (60 across in ";
		CHECK(nones == 1 && NthLogLineHas(noneWord, none0, word) && (k || NthLogLineHas(noneWord, none0, ") met GuardRail01 ")) && starts == 1 &&
		          NthLogLineHas("sidestep: PostA (layer 1) narrow ", let0, "to the left, both sides open, the other one taken") && g_ssPassed && g_ssLatAtPost < -40.0f,
		      "\"sidestep: none for PostA: %s..\" (%d), then \"... to the left, both sides open, the other one taken ...\" (%d), past the post %.0f left of the old line (over 40; the lane's ray alone: to the right, into it)", word,
		      nones, starts, -g_ssLatAtPost);
		DoneRiding();
	}
	Fixed66(false);
	/* 10: an actor dead ahead */
	printf("Sidestep: an actor's capsule (layer 30) dead ahead: never a sidestep:\n");
	{
		UpToSpeed(0.0f);
		int ss0 = LogLines(startWord);
		FakePlane *w = Thing49(0, edge + 800.0f, 0.0f, 10.0f, 0.0f, 60.0f, NULL);
		w->layer = 30;
		RunFrames(800);
		CHECK(LogLines(startWord) == ss0 && LogLines("stepped round toward its open side from 250 a second, up to 12 deg at 40 deg/s for 60 across, then back to the line (Sidestep); ") >= 1,
		      "no \"sidestep:\" line (%d), Sidestep=40 read (the settings line's words)", LogLines(startWord) - ss0);
		DoneRiding();
	}
	RewriteIni("Sidestep=40", "Sidestep=0");
	g_onFrame = GlimpseFrame;
}

/* SlideRestore and FaceAlongKeep (2026-11-02a; test 48's "stopping me randomly" alongside a rail): AlongTests' world (the capsule
 * held at a face and kept at 0.4 of its motion along it, the speed by the game's curve), at 900. Each with its key 0 written too
 * (2026-11-01a). */
static int g_s50Mode;              /* 1: the late hold (the camera turned 12 deg into the face 0.1 s after the contact); 3: the posts (the face swapped for one 0.1 s on) */
static float g_s50After, g_s50Went, g_s50T;
static bool g_s50Turned, g_s50Swapped;
static FakePlane *g_s50Post;       /* mode 3: put on, the face off, 0.1 s after the face went up; off 0.25 s after */
static void Slide50Frame(float dt)
{
	AlongFrame(dt);
	if (g_s50Mode == 3) {
		g_s50T += dt;
		if (!g_s50Swapped && g_s50T >= 0.1f && g_s50Post) {
			g_planes[0].on = false;
			g_s50Post->on = true;
			g_s50Swapped = true;
		}
		if (g_s50Swapped && g_s50T >= 0.35f && g_s50Post)
			g_s50Post->on = false;   /* on 0.25 s: a line 0.25 s after the face's */
		return;
	}
	if (!g_alongW || !g_alongTouched)
		return;
	float since = g_alongT - g_alongTc;
	if (g_s50Mode == 1 && !g_s50Turned && since >= 0.1f) {
		g_camYaw = PlayerHeading() - 12.0f / DEG;   /* into the face, on the left: the velocity along it 22 deg off the heading */
		g_s50Turned = true;
	}
	if (g_s50Mode == 1 && since >= 0.4f && since <= 0.65f) {
		float in = hypotf(MoveInput()[0], MoveInput()[1]);
		g_s50After = in > g_s50After ? in : g_s50After;
	}
	if (since >= 1.0f && since - dt < 1.0f)
		g_s50Went = (PlayerPos()[0] - g_alongContact[0]) * g_alongU[0] + (PlayerPos()[1] - g_alongContact[1]) * g_alongU[1];
}
static void SlideTests50(void)
{
	static const char noFace[] = "slide: no face alongside seen in the last half second, the velocity ", backUp[] = "; back up from 0.", toBind[] = " to what it was when the cap began to bind ";
	static const char keptWord[] = "(the rays either side don't say so now; the same face confirmed ", wallVerdict[] = ": a wall verdict (the face rays)";
	static uint8_t *postObj;
	if (!postObj)
		postObj = NewNode(*(void ***)g_wallObj, "FakePost", 0);
	g_onFrame = Slide50Frame;
	g_capSlip = 0.4f;
	g_gameCurve = true;
	RewriteIni("Climb=1\n", "Climb=0\n");   /* the low face's 25 is under ClimbTop: no climb's boost (it would end the hold) */

	/* 1: the late hold (test 48's 18:10:56: "0.79 ... held to the measured speed", then "the velocity 15 deg off ...: the throttle
	 * held at 0.68"): the 10 deg face of AlongSlide, but 25 high (the face rays' axle ray passes over it: no face alongside, no
	 * "seen"), the capsule held at it; the velocity along it 10 deg off the heading (no veer) till the camera turns 12 deg into
	 * it 0.1 s after the contact (22 deg off: the hold starts about 0.2 s later, the cap bound since the contact). */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("SlideRestore=0.5", "SlideRestore=0");
		printf("SlideRestore (test 48's 18:10:56): %sa face 25 high (under the face rays) whose line crosses the heading 325 ahead, 10 deg off it, on the left, at 900, the camera turned 12 deg into it 0.1 s after the contact, W held: %s:\n",
		       off ? "SlideRestore=0 written: " : "",
		       off ? "the hold from what the cap has left, as in 2026-11-01a" : "the hold back up to what the throttle was when the cap began to bind (\"; back up from 0.. to what it was when the cap began to bind .. s before (SlideRestore)\")");
		AlongOn(3500);
		int noFace0 = LogLines(noFace), offText = LogLines("instead of capped to the measured speed (SlideHold); ");
		RunFrames(400);
		FakePlane *w = AlongPlane(0, 325.0f, 10.0f, 0.0f, CAP_STEP);
		w->top = 25.0f;
		g_s50Mode = 1;
		g_s50Turned = false;
		g_s50After = -1.0f;
		g_s50Went = -1.0f;
		g_alongT = 0.0f;
		RunFrames(1500);
		g_s50Mode = 0;
		int starts = LogLines(noFace) - noFace0;
		float held = NthLineNumber(noFace, noFace0, "the throttle held at "), ago = NthLineNumber(noFace, noFace0, toBind);
		bool words = NthLogLineHas(noFace, noFace0, backUp) && NthLogLineHas(noFace, noFace0, toBind) && NthLogLineHas(noFace, noFace0, " s before (SlideRestore))");
		if (off)
			CHECK(g_alongTouched && starts >= 1 && !words && held < 0.8f && g_s50After >= 0.0f && g_s50After < 0.85f && offText >= 1,
			      "touched it (%s), the hold's line (%d) without \"back up\", held at %.2f (under 0.8), the input %.2f at the most 0.4-0.65 s after the contact (under 0.85); the settings line without SlideRestore's words (%d)",
			      g_alongTouched ? "yes" : "no", starts, held, g_s50After, offText);
		else
			CHECK(g_alongTouched && starts >= 1 && words && held >= 0.95f && ago >= 0.1f && ago <= 0.5f && g_s50After >= 0.9f,
			      "touched it (%s), \"%s.. deg off the heading (SlideAngle 15): the throttle held at %.2f ... (... would have capped it at ..%s..%s%.2f s before (SlideRestore))\" (%d; 0.95 or more, 0.1-0.5 s), the input %.2f at the most 0.4-0.65 s after the contact (0.9 or more)",
			      g_alongTouched ? "yes" : "no", noFace, held, backUp, toBind, ago, starts, g_s50After);
		Keys(0.0f, 0.0f);
		AlongClear();
		if (off)
			RewriteIni("SlideRestore=0", "SlideRestore=0.5");
	}

	/* 2: the flank unconfirmed (test 48's 18:38:23, a station wagon 8 deg off: "slide: over after 0.01 s: a wall verdict (the face
	 * rays)", 713 -> 55): a tall face 6 deg off the heading (met at 6 the axle ray's hit stays ahead of the front wheel while the
	 * capsule slides along it: 172 from the axis), confirmed alongside before the contact, that ends 300 along its line past where
	 * it crosses the heading: the rays' hit 24 away from it (229 further along) runs off its end 0.2 s after the contact, the axle
	 * ray's about 0.6 s later. */
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("FaceAlongKeep=1.0", "FaceAlongKeep=0");
		printf("FaceAlongKeep (test 48's 18:38:23): %sa tall face 6 deg off the heading, on the left, crossing it 325 ahead at 900, ending 300 along it past there, the capsule sliding along it, W held: %s:\n",
		       off ? "FaceAlongKeep=0 written: " : "",
		       off ? "the side ray's hit off its end: a wall by its steepness, the slide's hold ended by the wall verdict, as in 2026-11-01a"
		           : "kept alongside (\"(the rays either side don't say so now; the same face confirmed .. s ago: FaceAlongKeep)\"), no wall verdict, the slide on");
		AlongOn(3500);
		int kept0 = LogLines(keptWord), over0 = LogLines(wallVerdict), wall0 = LogLines("rays: a wall ahead ("), lost0 = LogLines("(alongside by its normal, 6 deg off the heading, but the rays either side don't say so: toward it hit ");
		int offText = LogLines("a post or a trunk staying across (FaceAlongRays=1); ");
		RunFrames(400);
		AlongPlane(0, 325.0f, 6.0f, 300.0f, CAP_STEP);
		g_s50Mode = 2;
		g_s50Went = -1.0f;
		g_alongT = 0.0f;
		RunFrames(1500);
		g_s50Mode = 0;
		int kept = LogLines(keptWord) - kept0, overs = LogLines(wallVerdict) - over0, walls = LogLines("rays: a wall ahead (") - wall0, lost = LogLines("(alongside by its normal, 6 deg off the heading, but the rays either side don't say so: toward it hit ") - lost0;
		if (off)
			CHECK(g_alongTouched && kept == 0 && lost >= 1 && NthLogLineHas("(alongside by its normal, 6 deg off the heading, but the rays either side don't say so: toward it hit ", lost0, ", away found nothing within ") && overs >= 1 &&
			          g_s50Went >= 0.0f && g_s50Went < 220.0f && offText >= 1,
			      "touched it (%s), no kept line, a wall line \"(alongside by its normal, 6 deg off the heading, but the rays either side don't say so: toward it hit .. along, away found nothing within ..)\" (%d), \"slide: over after ..%s\" (%d), "
			      "%.0f along it in the second after the contact (under 220); the settings line without FaceAlongKeep's words (%d)", g_alongTouched ? "yes" : "no", lost, wallVerdict, overs, g_s50Went, offText);
		else
			CHECK(g_alongTouched && kept >= 1 && NthLogLineHas(keptWord, kept0, "rays: a face alongside, 6 deg off the heading: ") && NthLogLineHas(keptWord, kept0, " s ago: FaceAlongKeep)") && overs == 0 && walls == 0 && g_s50Went >= 250.0f,
			      "touched it (%s), \"rays: a face alongside, 6 deg off the heading: .. left alone %s.. s ago: FaceAlongKeep)\" (%d), no wall line (%d), no \"slide: over after ..%s\" (%d), %.0f along it in the second after the contact (250 or more)",
			      g_alongTouched ? "yes" : "no", keptWord, kept, walls, wallVerdict, overs, g_s50Went);
		Keys(0.0f, 0.0f);
		AlongClear();
		if (off)
			RewriteIni("FaceAlongKeep=0", "FaceAlongKeep=1.0");
	}

	/* 3: the keep goes by the object and the normal: the tall 6 deg face confirmed alongside, swapped 0.1 s on for a post 20 across
	 * 380 ahead (the face gone, the post on for 0.25 s): of the same object, its normal 15 deg off: kept; another object (FakePost):
	 * a wall, its own confirmation missing as before; the same object across the way (40 deg): a wall. */
	printf("FaceAlongKeep: the tall 6 deg face confirmed alongside at 900, swapped 0.1 s on for a post 20 across 380 ahead whose normal reads 15 deg off the heading: of the same object, kept; FakePost, a wall; "
	       "the same object at 40 deg, a wall:\n");
	{
		AlongOn(3500);
		static const char postLost[] = "(alongside by its normal, 15 deg off the heading, but the rays either side don't say so: toward it found nothing within ";
		int got[3][3];   /* per post: kept lines, FakePost walls unconfirmed, FakeWall walls with no alongside word */
		for (int p = 0; p < 3; p++) {
			int kept0 = LogLines(keptWord), lost0 = LogLines(postLost), across0 = LogLines("(FakeWall, layer 1), the throttle eased to ");
			RunFrames(400);
			AlongPlane(0, 325.0f, 6.0f, 0.0f, CAP_NONE);
			g_s50Post = AlongPlane(1, 470.0f, p == 2 ? 40.0f : 15.0f, 10.0f, CAP_NONE);   /* 380 ahead when it goes up, 155 when it goes */
			g_s50Post->what = p == 1 ? postObj : NULL;
			g_s50Post->on = false;
			g_alongW = &g_planes[0];
			g_s50Mode = 3;
			g_s50T = 0.0f;
			g_s50Swapped = false;
			RunFrames(500);
			g_s50Mode = 0;
			g_s50Post = NULL;
			AlongClear();
			got[p][0] = LogLines(keptWord) - kept0;
			got[p][1] = LogLines(postLost) - lost0;
			got[p][2] = LogLines("(FakeWall, layer 1), the throttle eased to ") - across0;
			RunFrames(600);
		}
		CHECK(got[0][0] >= 1 && got[1][0] == 0 && got[1][1] >= 1 && got[2][0] == 0 && got[2][2] >= 1,
		      "the same object at 15 deg: %d kept line(s); FakePost: %d kept, %d \"%s...\"; the same object at 40 deg: %d kept, %d wall line(s) for FakeWall (2026-11-01a: none kept)",
		      got[0][0], got[1][0], got[1][1], postLost, got[2][0], got[2][2]);
		Keys(0.0f, 0.0f);
	}

	/* 5: the settings line's words for both, on (the run's INI). */
	CHECK(LogLines("(SlideHold), from what the throttle was when the cap began to bind if that was within 0.5 s (SlideRestore); ") >= 1 &&
	          LogLines("(FaceAlongRays=1), one confirmed kept alongside for 1 s while it is the same face, its normal still says so and it is ahead (FaceAlongKeep); ") >= 1,
	      "the steer settings line: \"...(SlideHold), from what the throttle was when the cap began to bind if that was within 0.5 s (SlideRestore)\" and \"...(FaceAlongRays=1), one confirmed kept alongside for 1 s while it is the same face, its normal still says so and it is ahead (FaceAlongKeep)\"");
	RewriteIni("Climb=0\n", "Climb=1\n");
	Keys(0.0f, 0.0f);
	RunFrames(1000);
	g_capSlip = 1.0f;
	g_gameCurve = false;
	g_onFrame = ClimbFrame;
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
}

/* LowObstacleThrottle (2026-11-02a; test 48's "a kerb at speed slows down too much"): mode 0's low face at 65 deg (40 tall, its foot
 * 150 ahead of the rider wherever they go), W held 2 s from rest, against a full-throttle 2 s from rest; LowObstacleThrottle=0
 * written too (ObstacleThrottle's 0.55, as in 2026-11-01a; mode 0 rides it at 0). */
static void LowObstacleTests50(void)
{
	static const char lowWord[] = "rays: an obstacle lower than 1.5 wheel radii ahead (";
	g_onFrame = ClimbFrame;
	float p0[2];
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
	Mark(p0);
	Keys(0.0f, 1.0f);
	RunFrames(2000);
	float fullRun = Moved(p0);
	Keys(0.0f, 0.0f);
	for (int k = 0; k < 2; k++) {
		bool off = k == 1;
		if (off)
			RewriteIni("[Steer]\n", "[Steer]\nLowObstacleThrottle=0\n");
		printf("LowObstacleThrottle (test 48's kerbs): %sa low face of 65 deg, 40 tall, its foot 150 ahead of the rider, W held 2 s from rest: %s:\n", off ? "LowObstacleThrottle=0 written: " : "",
		       off ? "held to ObstacleThrottle's 0.55, as in 2026-11-01a" : "held to 0.85 (\"held to 85% (LowObstacleThrottle)\")");
		GetOffAndOn(45.0f);   /* at rest, the INI read again */
		g_camYaw = PlayerHeading();
		int low0 = LogLines(lowWord), tagged0 = LogLines("the throttle held to 85% (LowObstacleThrottle)"), at55 = LogLines("the throttle held to 55%");
		int onText = LogLines("holding the throttle to 0.85 (LowObstacleThrottle; the others 0.55, ObstacleThrottle)"), offText = LogLines("holding the throttle to 0.55 (ObstacleThrottle)");
		FakePlane *face = Obstacle(0, 150.0f, 40.0f, CAP_NONE, 10.0f, 1, NULL);
		face->follow = 150.0f;
		face->slant = 65.0f;
		Mark(p0);
		Keys(0.0f, 1.0f);
		RunFrames(2000);
		float moved = Moved(p0);
		Keys(0.0f, 0.0f);
		face->on = false;
		face->follow = face->slant = 0.0f;
		int lows = LogLines(lowWord) - low0, tagged = LogLines("the throttle held to 85% (LowObstacleThrottle)") - tagged0, held55 = LogLines("the throttle held to 55%") - at55;
		if (off)
			CHECK(fabsf(moved - 0.55f * fullRun) <= 0.1f * fullRun && lows >= 1 && tagged == 0 && held55 >= 1 && offText >= 1,
			      "rides %.0f in 2 s (0.55 of %.0f at full throttle, within 10%%), \"%s65 deg): ... the throttle held to 55%%\" (%d of %d), no LowObstacleThrottle line; the settings line \"holding the throttle to 0.55 (ObstacleThrottle)\" (%d)",
			      moved, fullRun, lowWord, held55, lows, offText);
		else
			CHECK(fabsf(moved - 0.85f * fullRun) <= 0.1f * fullRun && tagged >= 1 && held55 == 0 && onText >= 1,
			      "rides %.0f in 2 s (0.85 of %.0f at full throttle, within 10%%; 2026-11-01a: 0.55), \"...the throttle held to 85%% (LowObstacleThrottle)\" (%d of %d), no 55%% line; the settings line \"holding the throttle to 0.85 (LowObstacleThrottle; the others 0.55, ObstacleThrottle)\" (%d)",
			      moved, fullRun, tagged, lows, onText);
		RunFrames(2500);   /* rolled off */
		if (off)
			RewriteIni("[Steer]\nLowObstacleThrottle=0\n", "[Steer]\n");
	}
	GetOffAndOn(45.0f);
	g_camYaw = PlayerHeading();
}

