		Ini57Drop("Sound", table[i]);
	SndGears17a63();   /* 2026-11-21a: the code's defaults then */
	for (int i = 0; i < 4; i++)
		Ini57Drop("Steer", drive[i]);
	Ini57Drop("Sound", "SpeedMap");
