	LookGetOn(1000);
	RunFrames(1500);
	int sameFrames = g_tip51Frames, sameBad = g_tip51FovBad, sameLines = LogLines("camera: the world FOV") - fl0;
	TipRec51(false);
	LookGetOff();
	*camFov = 70.0f;
	LookGetOn(1000);
	RunFrames(300);
	bool at90 = *camFov == 90.0f;
	const char *sameText = "camera: the world FOV back to 70 (CMB_ViewFov now the FOV it was)";
