	RunFrames(2500);
	V57Reset(1);
	RunFrames(2300);
	g_v57Measure = 0;   /* measuring stops, the figures kept */
	float offOn = V58Median(g_v58Off, g_v58OffN);
	int shownOn = g_v57Shown[0];
	l = LastLogLine("view: lock: ");
