		float spineHead = Dist3((const float *)(g_bodyNodes[2] + 0xA0), (const float *)(g_bodyNodes[8] + 0xA0));
		float bellyHead = Dist3((const float *)(g_bodyNodes[10] + 0xA0), (const float *)(g_bodyNodes[8] + 0xA0));
		cageR[0] = spineHead + 10.0f;
