	Ini54Set("View", "BodyEye", "0,2,-0.5");   /* 2026-11-17a: 16b's default (now 0,6,-3; BodyLeanMax 40, DEF61 pins 35): these checks are 16b's */
	Ini56Unset("View", "BodyWorn");
