		ObjectWorld(g_viewShape[0][i], g_lookParts[i].c, e);
		boundWorst = fmaxf(boundWorst, Dist3(b, e) + fabsf(b[3] - g_lookParts[i].r));
		inside += Dist3(b, (const float *)(g_viewRoot[0] + 0xB0)) + b[3] <= rootR + 0.01f;
