	float *lp = (float *)(n + 0x60), *wp = (float *)(n + 0xA0), *wb = (float *)(n + 0xB0);
	lp[0] = 0.0f; lp[1] = 0.0f; lp[2] = -56.0f;
	*(float *)(n + 0x6C) = 0.3f;
	wp[0] = 1.0f; wp[1] = 2.0f; wp[2] = 3.0f;
	*(float *)(n + 0xAC) = 0.375f;
	wb[0] = 1.0f; wb[1] = 2.0f; wb[2] = 24.0f; wb[3] = 45.0f;
