	RunFrames(600);
	KitStack57(2, pipboy, closed);
	RunFrames(600);
	*(uint32_t *)(g_kitTrnsOther + 0x14) = 0x00012345u;
	*(uint8_t **)(g_kitMenu57 + 0x110 + 0xE0) = g_kitTrnsOther;
	KitStack57(1, g_kitMenu57, NULL);
