	memcpy(m + 0x30, rot, sizeof(rot));
	memcpy(m + 0x70, rot, sizeof(rot));
	float place[3] = { -2.6f, 266.1f, 17.0f }, bound[4] = { 0.0f, 268.9f, 54.9f, 109.6f };
